programs.sol:
"""A lexical personal-reference signal, strongest for 'you', 'your', and '你'.

Recognize listed pronouns in several languages and Chinese tokens containing
你/您. English addressee responses diminish after recent addressee mentions;
a decaying count measures repetition. Clause introductions, question auxiliaries,
and thanks adjust 'you'. Smaller rules cover pronoun case/word boundaries,
'let me', contractions, polite forms, and the chat role 'user'.
Reset the mention count at document boundaries; predict zero otherwise.
"""
from math import sqrt

READS = ()

# Personal/possessive pronouns: lower-case forms at a word boundary.
ENGLISH = {
    'I': .53, 'me': .95, 'my': 1.23, 'mine': .20, 'myself': 1.38,
    'we': .90, 'us': 1.07, 'our': 1.35, 'ours': .59, 'ourselves': 1.61,
    'he': -.07, 'him': .38, 'his': .33, 'himself': .78,
    'she': .10, 'her': .50, 'hers': .11, 'herself': .87,
    'they': .55, 'them': .65, 'their': .61, 'theirs': .31,
    'themselves': .95, 'it': -.05, 'its': -.21, 'itself': .38,
    'thou': .43, 'thee': .59, 'thy': .67, 'ye': .60,
}
SECOND = {'you': 4.84, 'your': 5.48, 'yours': 3.42,
          'yourself': 3.32, 'yourselves': 3.32}
# Other languages' second-person forms, including polite/plural forms.
ADDRESSEE = {
    '你': 4.66, '你们': 4.4, '你們': 4.4, '你的': 3.75,
    '您': 3.29, '您的': 3.26, 'あなた': 4.16,
    'vous': 2.53, 'votre': 2.75, 'vos': 1.32, 'tu': .86,
    'você': 3.31, 'usted': 2.10, 'bạn': 3.0,
    'вы': 1.70, 'ваш': 3.58, 'вам': 2.68, 'вас': 2.75,
    'вашего': 2.42, 'ваши': 1.83, 'sie': 1.24, 'du': .30,
}
OTHER_REFERENCE = {
    '我': 1.03, '我们': 1.02, '我們': 1.02, '我的': .81,
    '我们的': .90, '自己': .99, '自己的': .79, '大家': .94,
    '他们': .51, '他們': .56, '咱们': .69, '自分': .40,
    'ich': .39, 'wir': .62, 'unser': .85,
    'je': .33, 'nous': .49, 'notre': .64,
    'мы': .46, 'мне': .91, 'нам': .48, 'нас': .61,
    'tôi': .42, 'jag': .33,
}
POLITE_JAPANESE = {'お', 'ご', 'さん', 'ください'}
CLAUSE_INTRODUCERS = {'what', 'how', 'where', 'when', 'why', 'which', 'that'}
QUESTION_AUXILIARIES = {
    'can', 'could', 'do', 'did', 'would', 'will', 'should', 'are', 'have', 'must'
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    _, recent, previous = (doc, 0.0, '') if start else carry
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    spaced = bool(token) and token[0].isspace()
    capital = bool(word) and word[0].isupper()
    address = lower in SECOND or word in ADDRESSEE or lower in ADDRESSEE
    address = address or '你' in word or '您' in word
    value = 0.0

    if lower in SECOND:
        value = SECOND[lower]
        if lower == 'you':
            value -= .83 * sqrt(recent)
            value -= .32 * (not spaced) + .28 * capital
            value -= .22 * (capital and not spaced)
            if previous == 'if':
                value -= .69
            elif previous in QUESTION_AUXILIARIES:
                value -= .92
            elif previous in CLAUSE_INTRODUCERS:
                value += .67
            elif previous in {'thank', 'thanks'}:
                value -= 1.35
        elif lower == 'your':
            value -= 1.12 * sqrt(recent)
            value -= .61 * (not spaced) + .12 * capital
        else:
            value -= .47 * sqrt(recent)
        if start:
            value -= 1.95
    elif word == 'I':
        value = .53 if spaced else .28
        if start:
            value = .01
    elif lower in ENGLISH:
        value = ENGLISH[lower]
        if lower == 'me' and previous == 'let':
            value = 0.0
        if capital:
            value -= {'my': .42, 'our': .17, 'he': .15, 'she': .10,
                      'his': .22, 'her': .14, 'me': .75, 'us': .67}.get(lower, 0)
        if not spaced:
            value = {'my': .78, 'we': .70, 'our': (1.2 if capital else .30), 'me': .02,
                     'us': .02, 'ours': .04}.get(lower, value)
        if word in {'US', 'ME'}:
            value = -.08
    elif word in ADDRESSEE or lower in ADDRESSEE:
        value = ADDRESSEE.get(word, ADDRESSEE.get(lower, 0.0))
        if not spaced and word == lower and word.isalpha():
            # Unspaced European fragments can also be parts of longer words.
            if all(ord(c) < 0x2000 for c in word):
                value *= .25
        if word == 'sie':  # Lowercase German 'she/they', not polite 'you'.
            value = .41
    elif '你' in word:
        value = 3.6 if word.endswith('你') else 2.6
    elif '您' in word:
        value = 2.5 if word.endswith('您') else 2.0
    elif word in OTHER_REFERENCE or lower in OTHER_REFERENCE:
        value = OTHER_REFERENCE.get(word, OTHER_REFERENCE.get(lower, 0.0))
    elif word in POLITE_JAPANESE:
        value = .70
    elif lower == 'user':
        value = .66 if previous == '<|im_start|>' else .30
    elif lower == 'please':
        value = .50
    elif word in {"'re", '’re'} and previous in {'you', 'we', 'they'}:
        value = .30
    elif word in {'ınız', 'iniz'}:
        # Turkish second-person plural/polite possessive suffixes.
        value = 1.7

    return (doc, .96 * (recent + address), lower), float(value)

programs.haiku:
"""Pronoun detector for layers.0.mlp.down_proj component 5696.

What it does: the component responds to the word being read at the current position.
It is strongest on second-person "you" and "your" (about 4.4 in its activation units),
moderate on first-person plural and possessive words ("we", "my", "our", "myself", and
their translations) at about 1, weak on "they/them/their" and "I/me" at about 0.3-0.5,
and essentially zero on every other token. It reads only the current token, so it
needs no carry from earlier positions.

Why it matters: almost all of the component's variance is on "you" and "your" tokens.
"""

READS = ()

# Second-person addressee words, English and other languages.
YOU = {
    "you", "your", "yours", "yourself", "yourselves",
    "vous", "votre", "vos", "вы", "вас", "вам", "ваш", "você", "您", "你", "你们", "你們",
}
# First-person plural and possessive words ("we", "my", "our").
WE = {"we", "my", "our", "myself", "ourselves", "us", "我", "我们", "我的", "wir", "nous"}
# Third-person plural and possessive words.
THEY = {"they", "them", "their", "themselves", "her", "his", "him", "sie", "ihre"}
# First-person singular.
ME = {"i", "me", "mine"}

# Predicted activation for each group, from the average over sampled training text.
VALUE = {"you": 4.4, "we": 1.0, "they": 0.5, "me": 0.3}


def step(carry, prefix, upstream):
    """Activation at the newest token: a lookup of its word in the groups above."""
    word = prefix.token_strings[-1].strip().lower()
    if word in YOU:
        return None, VALUE["you"]
    if word in WE:
        return None, VALUE["we"]
    if word in THEY:
        return None, VALUE["they"]
    if word in ME:
        return None, VALUE["me"]
    return None, 0.0

programs.luna:
"""Predict a lexical person-reference signal, strongest for direct address."""

READS = ()

HIGH = {"you", "your", "yours", "yourself", "yourselves"}
FIRST = {"i", "me", "my", "mine", "we", "us", "our", "ours"}
OTHER = {"she", "her", "hers", "they", "them", "their", "theirs", "his", "him"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in HIGH:
        return None, 4.8
    if word in FIRST:
        return None, 0.9
    if word in OTHER:
        return None, 0.4
    if word in {"user", "お客様", "自己", "mí", "их", "нам", "unsere"}:
        return None, 0.65
    return None, 0.0

programs.sol:
"""Detect separation vocabulary, especially 'away', with common phrase senses.

'Away' is strongest, but the death and immediacy idioms ('passed away',
'right away') and distance phrases are weaker. Related removal/escape words
have smaller negative responses. There are also weaker spelling responses to
'ay'/'way' pieces, and to 'summary'. Numbers are rounded, grouped fits to
training activations, not a claim about every sense of these words. Unlisted
tokens are silent; the program does not try to reproduce the small background.
"""
READS = ()

REMOVAL = {'remove', 'removes', 'removed', 'removing', 'removal', 'removable'}
ESCAPE = {'escape', 'escapes', 'escaped', 'escaping'}
DEPARTURE = {'depart', 'departed', 'departing', 'departure', 'departures'}
DISAPPEAR = {'disappear', 'disappears', 'disappeared', 'disappearing'}
BREAKING = {'fall', 'falls', 'fell', 'falling', 'break', 'breaking', 'tear',
            'tearing', 'rip', 'ripping', 'cut', 'cutting'}
DISTANCE = {'far', 'further', 'farther'}
DISTANCE_UNITS = {'mile', 'miles', 'km', 'cm', 'mm', 'meter', 'meters',
                  'feet', 'distance', 'time', 'seconds', 'minutes', 'hours',
                  'days', 'weeks', 'months', 'years'}
# Chinese characters/words for leaving, escaping, remoteness, and discarding.
LEAVING = {'走', '走了', '离开', '離開', '离开了', '離', '而去', '离去',
           '远', '遠', '撤离', '掉', '掉了', '弃'}
FLEEING = {'逃', '逃跑', '逃离'}
FROM_WORDS = {'away', 'apart', 'aside', 'separate'} | DEPARTURE


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    token = raw.strip()
    word = token.lstrip('._-/(').lower()
    previous = ''
    if (prefix.position > 0 and
            prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2].strip().lower()

    if word == 'away':
        if previous in {'pass', 'passed', 'passing'}:
            value = -4.0 if previous == 'passed' else -5.1
        elif previous in {'right', 'straight'}:
            value = -5.9 if previous == 'right' else -6.3
        elif previous in DISTANCE:
            value = -6.5
        elif previous in DISTANCE_UNITS or previous.isdigit():
            value = -7.1
        elif previous in {'get', 'got', 'getting', 'walk', 'walking'}:
            value = -9.0
        elif token.startswith('-'):
            value = -7.0
        elif token[:1].isupper():
            value = -9.2
        else:
            value = -8.3 if raw.startswith(' ') else -7.8
    elif word == 'apart':
        value = -3.2 if previous in BREAKING else -2.55
        if token[:1].isupper():
            value = -2.25
    elif word == 'aside':
        value = -2.05
    elif word in {'getaway', 'runaway', 'giveaway', 'throwaway'}:
        value = -2.9
    elif word == 'aways':
        value = -5.4
    elif word in REMOVAL:
        value = -0.8
    elif word == 'separate':
        value = -0.78
    elif word in {'separated', 'separates', 'separating', 'separately',
                  'separation', 'separator'}:
        value = -0.3
    elif word in ESCAPE or word in DEPARTURE or word in DISAPPEAR:
        value = -0.78
    elif (word in {'goodbye', 'bye', 'evict', 'eviction', 'evapor'}
          or raw == ' rid'):
        value = -0.95
    elif token in LEAVING:
        value = -1.1
    elif token in FLEEING:
        value = -1.5
    elif word in {'weg', 'entfer', 'удал'}:
        value = -2.2 if word == 'entfer' else -1.2
    elif token in {'去', '离', '开'}:
        value = -0.45
    elif token == '远离':
        value = -3.2
    elif word == 'from' and previous in FROM_WORDS:
        value = -0.8 if previous == 'away' else -0.28
    elif word == 'of' and previous == 'rid':
        value = -0.47
    elif word == 'ay':
        value = -5.1 if previous == 'aw' else -0.62
    elif word in {'ays', 'eway'}:
        value = -0.55
    elif word == 'way':
        value = -0.47 if previous == 'a' or not raw.startswith(' ') else -0.07
    elif word in {'ways', 'anyway'}:
        value = -0.5 if word == 'ways' else -0.75
    elif word == 'off':
        value = -0.3
    elif word == 'summary':
        value = -0.7
    else:
        value = 0.0
    return None, value

programs.haiku:
"""Predicts layers.0.mlp.down_proj:5699, a component that goes negative on nouns naming
institutions and public or commercial venues: "university", "school", "hospital", "court",
"church", "museum", "hotel", "casino", "shop", "bank", "station", "company", and their Chinese
equivalents. The most institutional names (hospital, museum, academy, airport) give the most
negative values. Ordinary place words (town, city, country, road, building, home) and most
other nouns give nothing, so this is a response to institutions and venues, not to places
in general. Plurals count as singulars, and the "of" that continues a name ("University of",
"Museum of") responds as well. Chinese names are judged by their last character
(院 court or hospital, 校 school, 館 hall, 店 shop, 站 station, 公司 company).
"""

# Strongest: about -4 when the word appears.
STRONGEST = {"hospital", "museum", "academy", "airport"}

# Strong: about -2.7.
STRONG = {
    "university", "college", "school", "hotel", "casino", "stadium", "clinic", "mosque",
    "monastery", "factory", "preschool",
}

# Medium: about -2.
MEDIUM = {
    "court", "church", "library", "institute", "institution", "prison", "jail", "restaurant",
    "zoo", "cathedral", "palace", "gym", "embassy",
}

# Weak: about -1.3.
WEAK = {
    "bank", "store", "shop", "station", "club", "gallery", "mall", "resort", "depot",
    "pharmacy", "cinema", "theater", "theatre", "garden", "studio", "spa", "castle", "bakery",
    "cafe", "workshop", "laboratory", "park", "hall", "police", "league", "agency", "farm",
    "mansion", "temple", "chapel", "festival", "railway", "forum", "archives", "lodge",
    "parliament", "oven", "campus", "arena",
}

# Faint: about -0.6 (organizations and bodies that are often used in other senses).
FAINT = {
    "company", "center", "centre", "house", "party", "society", "army", "navy", "office",
    "bridge", "magazine", "newspaper", "radio", "camp", "village", "lab", "association", "firm",
    "ministry", "bureau", "council", "congress", "senate", "foundation", "commission",
    "facility", "mill", "mine", "kitchen",
}

# Chinese: last character of a name for a hospital, court, school or college; a hall or shop;
# a station, office, company or other venue; plus whole words for university and school.
CJK_COURT_SCHOOL = "院校"
CJK_HALL_SHOP = "館馆店寺廟庙"
CJK_VENUE = "站所公司园園场場局府厅台"

# "of" right after one of these continues the institution's name and responds too.
OF_AFTER = {
    "university", "museum", "college", "court", "school", "institute", "academy", "hospital",
}

READS = ()


def _level(word):
    """The value for a lowercase English word, plurals counted as singulars."""
    forms = [word]
    if word.endswith("ies"):
        forms.append(word[:-3] + "y")
    if word.endswith("s"):
        forms.append(word[:-1])
    for w in forms:
        if w in STRONGEST:
            return -4.0
        if w in STRONG:
            return -2.7
        if w in MEDIUM:
            return -2.0
        if w in WEAK:
            return -1.3
        if w in FAINT:
            return -0.6
    return 0.0


def step(carry, prefix, upstream):
    """One token at a time: look at the token being predicted and the one before it."""
    token = prefix.token_strings[-1].strip()
    word = token.lower()
    previous = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    value = _level(word)
    if value == 0.0 and word:
        if word in ("大学", "大學", "学校", "學校") or word[-1] in CJK_COURT_SCHOOL:
            value = -3.0
        elif word[-1] in CJK_HALL_SHOP:
            value = -2.5
        elif word[-1] in CJK_VENUE:
            value = -1.2
    if word == "of" and previous in OF_AFTER:
        value = -1.6
    return carry, value

programs.luna:
