    "combat", "battle", "battles", "battlefield", "veteran",
    "veterans", "guerrilla", "guerrillas", "marine", "marines",
    "cavalry", "tank", "tanks", "gun", "guns", "rifle", "bomb",
    "bombs", "missile", "missiles", "airforce", "guerra", "guerre",
    "guer", "krieg", "soldat", "militari", "militare", "waffen",
    "вооруж", "оруж", "войн", "战斗", "战争", "作战", "军事", "武器",
    "兵器", "战士", "軍事", "戦争", "戦闘", "戦士", "軍", "军",
    "兵", "軍隊", "军队", "軍訓", "军训", "전쟁", "군", "무기",
}

LEGAL_WORDS = {"criminal", "crime", "crimes", "sworn"}


def step(carry, prefix, upstream):
    word = "".join(
        char for char in prefix.token_strings[-1].casefold().strip()
        if char.isalnum()
    )
    if word == "武":
        return None, -6.5
    if word in {"weapons", "weapon", "military"}:
        return None, -1.2
    if word in CONFLICT_WORDS:
        return None, -0.75
    if word in LEGAL_WORDS or word in {"馬", "马", "melee"}:
        return None, -0.5
    return None, 0.0

programs.sol:
"""Two surface patterns: slash separators and adjacent r-bearing fragments.

Standalone slashes are positive, especially outside numeric fractions; slashes
fused to words are usually negative. Short fragments containing r also respond
when the preceding fragment contains r, most strongly near its end. Length and
word boundaries weaken this response. Accented Latin r and common Cyrillic,
Arabic and Thai equivalents are treated alike. State resets for each document.
These are approximate spelling rules, not a token-by-token activation table.
"""
import unicodedata

READS = ()
R_EQUIVALENTS = str.maketrans("рرร", "rrr")
VOWELS = frozenset("aeiou")


def spelling(text):
    text = unicodedata.normalize("NFD", text.strip().lower())
    return "".join(c for c in text if not unicodedata.combining(c)).translate(
        R_EQUIVALENTS
    )


def slash_response(text, previous, first):
    s = text.strip()
    if s in ("/", "／"):
        value = 0.92 if text.startswith(" ") else 0.85
        if previous.strip().isdigit():
            value -= 0.20
        if first:
            value = 1.10 if s == text else 0.84
        return 0.47 if "\n" in text else value
    if s.count("/") != 1:
        return 0.0
    if any(c.isalnum() for c in s):
        return -0.17 if s.startswith("/") else 0.0
    if "<" in s or "*" in s:
        return 0.0
    if "(" in s[s.index("/") + 1:]:
        return 0.47
    if s.endswith("/"):
        if "\n" in text:
            return 0.47
        if any(c in s for c in "\"'`"):
            return 0.64
        if "." in s or ":" in s:
            return 0.56
        if ")" in s:
            return 0.72
        return 1.02 if "_" in s else 0.80
    return 0.0


def rhotic_response(text, previous, first):
    s = spelling(text)
    if "r" not in s:
        return 0.0
    vowel_r_vowel = (len(s) >= 3 and s[0] in VOWELS
                     and s[1] == "r" and s[2] in VOWELS)
    strength = 1.2 * 0.65 ** max(0, len(s) - 2)
    strength *= s.count("r") ** 0.65
    if s.startswith("r"):
        strength *= 1.2
    if vowel_r_vowel:
        strength *= 1.9
    boundary = 0.25 if text[:1].isspace() else 1.0
    prior = spelling(previous)
    if first:
        adjacency = 0.48
    elif "r" in prior:
        distance = len(prior) - 1 - prior.rfind("r")
        adjacency = 0.44 ** distance * 0.84 ** max(0, len(prior) - 2)
    else:
        adjacency = 0.04 if prior and prior[-1] in "aeioulny" else 0.0
    return boundary * (strength * adjacency + 0.08 * vowel_r_vowel) - 0.012


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous = "" if first else carry[1]
    value = slash_response(text, previous, first)
    value += rhotic_response(text, previous, first)
    return (doc, text), float(value)

programs.luna:
"""Predict punctuation-like activations from the current token alone."""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]

    # A call closed with a semicolon is a strong statement boundary.
    if "();" in token:
        value = 0.80 if not token.endswith("\n") else 0.50
    elif ");" in token:
        value = 0.75 if not token.endswith("\n") else 0.32
    elif token.strip() == ";":
        value = 0.45
    elif ";" in token:
        value = 0.30
    elif "()" in token:
        value = 0.48
    elif token.endswith(".\n"):
        value = 0.12
    elif token.endswith("|\n"):
        value = 0.50
    # A closing brace followed by a blank line is a weak negative cue.
    elif token.endswith("}\n\n"):
        value = -0.10
    else:
        value = 0.0
    return None, value

programs.sol:
"""Description vocabulary, with a short grammatical after-effect.

Forms of 'describe' give the largest negative signal, followed by 'description'
and translations or word pieces. Related acts of explaining, specifying and
referring give smaller signals. Case and word boundaries modify the response.
The following article or preposition can retain some of the signal, especially
in 'description of' and 'referred to'. Everything else is predicted as zero.
This is a lexical approximation, not a general detector of descriptive prose.
"""
import re

READS = ()


def inflections(verb):
    """Ordinary English verb forms; 'refer' doubles its final consonant."""
    stem = verb[:-1] if verb.endswith('e') else verb
    past, plural = stem + 'ed', verb + ('es' if verb.endswith('s') else 's')
    if verb.endswith('y'):
        past, plural = verb[:-1] + 'ied', verb[:-1] + 'ies'
    if verb == 'refer':
        stem, past = 'referr', 'referred'
    return {verb, plural, past, stem + 'ing'}


DESCRIBE = inflections('describe')
REFER = inflections('refer')

VERBS = {}
for value, words in (
    (-1.7, 'characterize'),
    (-1.2, 'refer prescribe subscribe'),
    (-0.95, 'explain diagnose depict portray'),
    (-1.3, 'summarize delineate outline'),
    (-0.7, 'define denote specify identify discuss'),
    (-0.55, 'mention express attribute criticize classify'),
):
    for word in words.split():
        VERBS.update(dict.fromkeys(inflections(word), value))

# Related nouns, partial roots, and translations of description vocabulary.
# Despite is a weaker spelling-related response, not a descriptive synonym.
NOUNS = {
