          'are': -0.82, 'being': -0.66}
INFINITIVE_AFTER = {
    'can': -6.75, 'could': -5.78, 'cannot': -5.72,
    'may': -5.26, 'might': -4.36, 'must': -4.40,
    'should': -3.71, 'shall': -2.88, 'will': -2.31,
    'would': -2.32, 'to': -1.98, 'need': -3.9, "'ll": -1.22, "'d": -1.50,
}
PERFECT_AFTER = {'has': -3.73, 'have': -3.03, 'had': -2.75,
                 "'ve": -2.0}
NEGATED_STEMS = {'couldn': 'could', 'shouldn': 'should',
                  'wouldn': 'would', 'won': 'will', 'mustn': 'must'}

