    'être': {'peut': -5.88, 'peuvent': -6.37, 'doit': -5.12,
             'doivent': -5.15, 'pourrait': -5.64,
             'pour': -4.22, 'à': -3.66},
    'быть': {'может': -6.08, 'могут': -4.84, 'мог': -4.56,
             'должна': -3.75, 'должен': -3.56, 'должны': -3.81,
             'должно': -3.92, 'нужно': -2.41, 'необходимо': -2.61},
    'ser': {'pode': -5.70, 'podem': -5.60, 'puede': -4.00,
            'pueden': -3.32, 'deve': -3.51, 'debe': -3.14,
