    """Find the nearest relevant auxiliary in a short, unbroken phrase."""
    english = word in ('be', 'been')
    table = (INFINITIVE_AFTER if word == 'be' else
             PERFECT_AFTER if word == 'been' else FOREIGN_AFTER.get(word, {}))
    for gap, earlier in enumerate(reversed(history)):
