                 'là': -0.66, 'worden': -1.10}[word]
    elif raw == '被':
        value = 0.47  # Chinese passive marker.
    elif word == 'me' and previous_word == 'let':
        value = -0.74
    elif word == 'am':
        value = -0.63 if previous_word == 'i' else -0.07
    elif word in ('be', 'been'):
        default = -0.70 if word == 'be' else -3.0
        value, found = auxiliary_response(word, history, default)
        if not boundary:
            value = value * 0.65 if found else (-0.30 if word == 'be' else -2.85)
        if raw[:1].isupper():
            value = value * 0.75 if found else (-0.36 if word == 'be' else -2.2)
    return (doc, (history + (token,))[-4:]), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 5707: a "be-verb" detector.

It writes a negative value on forms of the verb "to be" that follow a subject or
auxiliary:
  * the bare infinitive " be" is strongly negative, most of all after a modal
    ("can be", "must be", "could be"), and less after "will"/"would"/"to";
  * "been" is moderately negative;
  * finite forms "is", "was", "were", "are", "am" are weakly negative.
Everywhere else the component is (almost) silent.
"""

READS = ()

MODALS = {" can", " could", " must", " may", " might", " should", " also", " cannot"}
FINITE = {" is": -1.0, " was": -1.0, " were": -1.0, " are": -1.2, " am": -1.0}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok == " be":
        prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
        return carry, -6.0 if prev in MODALS else -3.5
    if tok == " been":
        return carry, -3.7
    return carry, float(FINITE.get(tok, 0.0))

