programs.sol:
"""Approximate a D/R spelling-fragment response, not a semantic topic.

Dr/dr is strongest; der/dar and longer dr-initial fragments are weaker.
A short token ending in d primes its unspaced continuation, especially r
or vowel+r. Longer fragments and capitalized new words weaken this effect.
Selected Cyrillic/Arabic counterparts and accented vowels share the rules.
Small branches cover d-initial paths, document starts, and the dot in Dr.
"""
import math
import unicodedata

READS = ()
# Letter counterparts, not a token-ID lookup.
COUNTERPARTS = str.maketrans({
    'д': 'd', 'р': 'r', 'د': 'd', 'ر': 'r',
    'а': 'a', 'е': 'e', 'и': 'i', 'о': 'o', 'у': 'u',
    'н': 'n', 'л': 'l', 'م': 'm', 'ن': 'n', 'ا': 'a',
})


def normalize(text):
    text = unicodedata.normalize('NFD', text.lower().translate(COUNTERPARTS))
    return ''.join(c for c in text if not unicodedata.combining(c))


def fragment_response(s, raw):
    word = s.lstrip(' /.-_([{')
    if word.startswith('dr'):
        if len(word) == 2:
            return 1.68 if 'د' in raw else 2.36
        if word.startswith('dri'):
            if word in ('drive', 'drives'):
                return 1.29
            return 0.40 if word.startswith('drink') else 0.83
        if word.startswith('dru'):
            value = 1.26 if word.startswith('drug') else 0.33
            return value - (0.23 if len(word) > 4 else 0.0)
        return 0.53 if len(word) == 3 else 0.34
    if word in ('der', 'dar'):
        return 0.71
    if word in ('dur', 'dor'):
        return 0.38
    return 0.33 if s.startswith('/d') else 0.0


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    p, s = normalize(previous).strip(), normalize(raw)
    value = fragment_response(s, raw)

    if p.endswith('d') and s[:1].isalpha():
        size = sum(c.isalpha() for c in p)
        strength = math.exp(-0.45 * max(0, size - 2))
        if raw[:1].isupper() and not previous.strip().isupper():
            strength *= 0.35
        response = 0.04
        if s.startswith('r'):
            response = 1.67 + (1.19 if len(s) == 1 else 0.0)
        elif len(s) > 1 and s[0] in 'aeiou' and s[1] == 'r':
            response = 1.13
        elif s[0] in 'dn':
            response = 0.75
        elif s[0] in 'aolmy':
            response = 0.31
        elif s[0] in 'iu':
            response = 0.14
        if len(s) > 1 and s[0] in 'aeiou' and s[1] in 'nm':
            response += 0.36
        response += 0.36 * (len(s) == 1) + 0.17 * raw.isupper()
        response -= 0.34 * min(1.0, max(0, len(s) - 3) / 5)
        response -= 0.12 * p.endswith('ld')
        value += strength * response
    elif p.endswith('dr'):
        value += 0.75 if s.startswith('.') else 0.18

    if not previous and s.lstrip(' /.-_([{') in ('d', 'ad'):
        value += 1.24
    if len(p) > 1 and p[-2] == 'd' and p[-1] in 'aeiou':
        if s[:1].isalpha():
            value += 0.03 * math.exp(-0.45 * max(0, len(p) - 2))
    return (doc, raw), float(value)

