programs.sol:
"""Lexical use/utility/advantage signal, with a little phrase context.

This is not a semantic judgment: the character 利 (benefit/profit) also fires
in names. Forms of use, utility-module names, and translations of use or gain
have different strengths. 'Can use' and 'take advantage of' are stronger.
The tool-call opening has a strong positive level; other dialogue markers
have weaker positive or negative levels. Unrecognized text gets zero.
"""
READS = ()

DIALOGUE_MARKERS = {
    '<tool_call>': 1.75, '</tool_response>': -.21, '<think>': -.21,
    '<tool_response>': .096, '</think>': .089, '<|im_end|>': -.047,
}

# Tense, number, and adjectival forms of the same utility/gain vocabulary.
FORMS = {
    'used': .21, 'useful': .29, 'usage': .13, 'reuse': .30,
    'benefit': .61, 'benefits': .35, 'beneficial': .40,
    'advantages': .72, 'advantageous': .57,
    'disadvantage': .42, 'disadvantages': .51,
    'profit': .75, 'profits': .64, 'profitable': .45,
    'profitability': .49, 'lever': .66, 'leverage': .85,
    'leveraging': 1.15, 'utility': .20, 'utilities': .18,
    # Chinese/Japanese use, gain, advantage, and convenience.
    '利': 4.70, '利用': 3.90, '不利': 2.65, '有利': 2.70,
    '利于': 2.60, '有利于': 1.38, '充分利用': 2.42,
    '利益': 1.36, '利润': .96, '便利': .86, '优势': .70,
    '运用': 1.45, '運用': 1.41, '使用': .53, '借助': 1.28,
    '趁': 1.18, '趁着': .90, '充分': .75,
    'を利用': 2.03, 'を利用して': 1.61, 'を利用する': 1.35,
    'ご利用': .60,
    # Other languages' use/gain words, including tokenized word roots.
    '이용': 2.07, '활용': 1.24, 'ใช': .57, 'lợi': 2.17,
    'nutzen': 1.05, 'gebruik': .56, 'uso': .52, 'usando': .46,
    'menggunakan': .71, 'kullan': .45, 'kullanıl': .62,
    'استخدام': .78, 'メリット': .43,
    # Li/ri sound pieces: lexical spillover outside utility words.
    '리': .62, 'リ': .33, '莉': .78,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same = carry is not None and carry[0] == doc
    prev, char, taking = carry[1:] if same else ('', '', False)
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    name = word.lstrip('./_-\'’')
    value = FORMS.get(word, 0.0)
    if token in DIALOGUE_MARKERS:
        value = DIALOGUE_MARKERS[token]
    elif word == 'use':
        value = .90 if token[:1].isspace() else .72
        if token.strip() == 'Use':
            value = .83
        elif token.strip() == 'USE':
            value = .56
        elif not token[:1].isspace() and char.isalpha():
            value = .28  # fragments inside words, e.g. 'exc' + 'use'
        value += .28 if prev == 'can' else 0.0
    elif word == 'using':
        value = .67 if token[:1].isspace() else .45
        if token.strip() == 'Using' or not same:
            value = .73
        value += .10 if prev == 'by' else 0.0
    elif word == 'uses':
        value = .51 if token[:1].isspace() else .12
    elif name == 'use':
        value = 1.04  # attached to identifier punctuation
    elif name == 'util':
        value = 1.82 if word.startswith('.') else .95
    elif name == 'utils':
        value = .52 if word.startswith('.') else .31
    elif name.startswith(('utiliz', 'utilis')):
        value = .54 if name.endswith(('ed', 'é')) else .93
    elif word.startswith('exploit'):
        value = .87
    elif word.startswith(('использ', 'ольз')):
        value = .98 if word in {'использ', 'ольз'} else .75
        if word in {'используют', 'используется'}:
            value = .42
        elif word == 'ользоват':
            value = .11
    elif word == 'advantage':
        value = 1.09 + (.61 if taking else 0.0)
    elif word == 'of':
        value = {'use': .31, 'benefit': .54, 'advantages': .75}.get(prev, 0.)
        if prev == 'advantage':
            value = 1.37 if taking else .85
    elif word == '利':
        # Victory and war spoils are distinct compounds of the gain character.
        value = 2.90 if char in {'胜', '勝'} else 4.70
        if char in {'战', '戰'}:
            value = 5.95
    elif word == '用':
        value = 4.90 if char == '利' else .36

    char = token[-1:]
    if '\ufffd' in token and same:
        char = prefix.text_prefixes[-1][-1:]
        if char == '利':
            value = 6.40  # the final bytes completing the character
    taking = word in {'take', 'takes', 'taking', 'took'} or (
        taking and word in {'full', 'advantage'}
    )
    return (doc, word, char, taking), float(value)

programs.haiku:
"""Layer-0 MLP down_proj component 5712, as a word-concept detector.

It is a token-level detector for the idea of USING or BENEFITING, in English and
other languages, plus the start of a tool call. On a word it outputs a fixed
strength (its typical activation for that word); everywhere else it outputs 0.

Strengths, from the measured activations:
  * "利" / "利用" (Chinese "to use / profit"; also in 順利, "smooth"): about 4
  * "<tool_call>" (the tag that opens a tool call): about 1.75
  * code/English "util" stems (".util", "util", "Util"): about 1 to 2
  * use / utilize / leverage / exploit, in English, Russian, Korean, Vietnamese:
    about 0.9
  * benefit / advantage / profit words: about 0.8 ("advantage" 1.1)
  * "of" right after "advantage" ("take advantage of"): about 1.2; after
    other use/benefit words: about 0.4
  * Chinese 使用 / 运用 / 优势 / 有利于 and the bare character 用: about 0.4 to 0.6
  * "used" and "useful": about 0.25; "utils", "utility": about 0.3
Everything else is 0. The big activations are rare; most positions are near 0.
"""
READS = ()

USE_WORDS = {"use", "uses", "using", "utilize", "utilizes", "utilizing", "utilise", "utilized",
             "utilization", "leverage", "exploit", "exploited", "lever", "활용",
             "использовать", "использование", "использования", "использ", "использов"}
BENEFIT_WORDS = {"benefit", "benefits", "advantage", "advantages", "profit", "profits",
                 "advantageous", "lợi", "利益", "优势", "有利于", "的优势"}
CHINESE_USE = {"使用", "运用", "充分利用", "利用率"}


def step(carry, prefix, upstream):
    # Each position is scored from its own token only (plus the one before, for "of").
    tok = prefix.token_strings[-1]
    s = tok.strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if s == "<tool_call>":
        v = 1.75
    elif s == "of" and prev == "advantage":
        v = 1.2
    elif s == "of" and (prev in USE_WORDS or prev in BENEFIT_WORDS):
        v = 0.4
    elif s in ("利", "利用"):
        v = 4.0
    elif s == "用":
        v = 0.4
    elif "util" in s:
        v = 1.0 if s.endswith("util") else 0.3
    elif s in USE_WORDS:
        v = 0.9
    elif s in BENEFIT_WORDS:
        v = 0.8
    elif s in CHINESE_USE:
        v = 0.6
    elif s in ("used", "useful"):
        v = 0.25
    else:
        v = 0.0
    return carry, float(v)

