"""Approximate the component's strongest lexical cues: using something, its utility,
or the benefit it gives. It also marks the model's explicit tool-call boundary.
"""

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()

    if word == "<tool_call>":
        value = 1.75
    elif word in {"use", "uses", "used", "using"}:
        value = {"use": 0.94, "uses": 0.51,
                 "used": 0.23, "using": 0.68}[word]
    elif "util" in word:
        value = 1.25
