programs.sol:
"""Tokenized 'state' words: a strong negative lexical signal.

English state(s), code State identifiers, and several translations dominate.
United States is weaker; physical states are stronger than verbal uses.
Case and attached punctuation affect strength. Other tokens predict zero.
Only the preceding token is retained, resetting between documents.
"""
READS = ()

PHYSICAL = {
    'ground', 'excited', 'quantum', 'bell', 'solid', 'eigen', 'magnetic',
    'paramagnetic', 'antiferromagnetic',
}
VERBAL = {'we', 'you', 'they', 'i', 'can', 'could', 'shall', 'will',
          'would', 'must', 'officially', 'categorically', 'first'}
# Related state words, inflections, and translations: weaker lexical signals.
RELATED = (
    ({'stated', 'stating'}, -1.35),
    ({'estate', 'estates', 'interstate'}, -1.55),
    ({'statewide'}, -2.4),
    ({'stat', 'stats'}, -0.75),
    ({'estado'}, -2.0), ({'estados', 'état', 'états'}, -1.25),
    ({'stato', 'stati', 'stata'}, -0.85),
    ({'mode'}, -0.7), ({'modes'}, -1.0),
    ({'phase'}, -0.4), ({'phases'}, -0.7),
    ({'medicaid'}, -1.75),
)


def activation(token, previous, reset):
    word = token.strip()
    plain = word.lstrip('._-/,([')
    lower = plain.lower()
    prev = previous.strip().lower()
    if lower in {'state', 'states'}:
        plural = lower == 'states'
        if plural and prev == 'united':
            return -1.25 if previous[:1].isspace() else -1.5
        value = -4.35 if plural else -5.0
        if plural and (plain == 'STATES' or word.startswith('_')):
            value = -3.2
        elif not plural:
            if plain == 'State':
                value = -5.4 if token[:1].isspace() else -6.5
                if word.startswith('.'):
                    value = -5.6
                elif word.startswith('_'):
                    value = -4.4
                elif previous.endswith('\n'):
                    value = -6.0
            elif plain == 'STATE':
                value = -6.7 if word.startswith('_') else -5.8
            elif word.startswith('.'):
                value = -6.7
            if word.startswith(('-', '/')):
                value = -6.0
            elif word.startswith(('(', '[')):
                value = -4.0
            elif not token[:1].isspace() and prev in {'pro', 'rein', 'inter', 're'}:
                value = -2.4
        if prev in PHYSICAL:
            value -= 1.5
        elif prev in VERBAL:
            value += 0.9
        elif prev == 'member':
            value += 1.3
        elif prev == 'to':
            value += 0.5
        if reset and plain == 'State':
            value -= 1.0
        return value
    if plain.endswith('State'):
        # Common code uses: saved UI state, state hooks, getters and setters.
        return {'savedInstanceState': -0.4, 'useState': -1.8,
                'getState': -5.8, 'setState': -4.2}.get(plain, -3.6)
    for words, value in RELATED:
        if lower in words:
            return value
    if lower.startswith('static'):
        return -1.1 if lower in {'static', 'staticmethod'} else -0.4
    if lower.startswith(('statistic', 'statement')):
        return -0.25
    if lower.startswith('zust'):
        return -2.5
    if lower.startswith('состоя'):
        return -2.7
    if lower.startswith('государ'):
        return -1.0
    if word in {'态', '態'}:
        return -6.5 if word == '态' else -4.5
    if '状态' in word or '狀態' in word:
        return -3.8
    if '形态' in word or '形態' in word:
        return -3.5
    if word == '静态':
        return -2.2
    if '态' in word or '態' in word:
        return -0.7
    if word == '상태':
        return -3.6
    if word in {'国家', '國家', '省', '全省', '州'}:
        return -1.5 if word == '州' else -1.15
    if lower == 'of' and prev in {'state', 'states'}:
        return -1.8 if prev == 'state' else -1.1
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    reset = carry is None or carry[0] != document
    previous = '' if reset else carry[1]
    token = prefix.token_strings[-1]
    return (document, token), activation(token, previous, reset)

