"""Predict the component's sparse negative response to “state” vocabulary.
English state words are the clearest trigger; related words for a state or
province in other languages and nearby forms receive smaller responses.
"""
import re

READS = ()
_STATE = re.compile(r"(?<![a-z])state(?![a-z])", re.IGNORECASE)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    lower = word.casefold()
    if lower in {"state", "態", "状态", "的状态"}:
        return None, -5.0
    if word == "states":
        return None, -4.8
    if lower in {"states", "省", "州", "国家", "estate"}:
        return None, -1.4
    if lower in {"stated", "static", "statewide"}:
        return None, -1.2
    if lower in {"stats", "phase", "phases", "status"}:
        return None, -0.7
    if _STATE.search(lower):
        return None, -1.4
    return None, -0.003

programs.haiku:
"""Candidate 5: the letters at a token boundary. When a word is split into pieces, a piece
that ends in a consonant (p, f, b, v) is followed by a piece that begins with o or u
(no leading space), the component fires: it reads the spelled sound "po", "pu", "fo", ...
Strongest for "p" + "o" (lipo|protein, P|oder, gosp|odarka); Cyrillic and Greek look-alikes
(п, π) count as p, and о, ο count as o."""

# Look-alike letters, mapped to the Latin letter they look like.
CANON = {"п": "p", "π": "p", "о": "o", "ο": "o", "ό": "o", "ó": "o", "ô": "o", "ö": "o",
         "у": "u", "ů": "u", "ü": "u", "ú": "u"}

# Activation (in units of the component's usual size) for a letter pair across a token boundary.
PAIR = {("p", "o"): 1.8, ("p", "u"): 1.3, ("f", "o"): 0.6, ("f", "u"): 0.6,
        ("p", "e"): -0.35, ("p", "r"): 0.3, ("b", "o"): 0.2, ("v", "o"): 0.2}

READS = ()

def letter(ch):
    return CANON.get(ch.lower(), ch.lower())

def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    prev = prefix.token_strings[-2]
    if not prev or not cur or cur[0].isspace():
        return None, 0.0
    return None, PAIR.get((letter(prev[-1]), letter(cur[0])), 0.0)

