import unicodedata

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].casefold()
    if "о" in token or "у" in token:
        return None, 0.035
    greek = unicodedata.normalize("NFD", token)
    if "ο" in greek or "υ" in greek:
