PLEASE = {"please"}
OTHER_LANGUAGE_REQUESTS = {"请", "請", "ください", "下さい", "ご", "bitte"}
COURTESY = {"sorry", "thank", "thanks", "kindly", "pleased", "pleasure", "apologize", "apologise"}
OPENERS = {"let", "see", "just", "alternatively", "click", "hello", "simply", "okay", "oh", "note"}


