"""A spelling-sensitive question/relative-word feature.

Lowercase 'what', 'how', and 'why' respond most strongly. A preceding
nonletter token or conjunction weakens them; prepositions strengthen
embedded questions and relatives. Capitalized starters have separate
weights at document starts and after '#' markers. 'What', 'How', and
'Why' weaken after line breaks. Several non-English question words also
fire. Other tokens predict zero. Only the current and previous token are
used; the previous token is ignored across document boundaries.
"""
READS = ()

# Each pair is (space-prefixed token, token without a leading space).
WORDS = {
    'what': (3.8, 2.2), 'how': (3.8, 2.35), 'why': (2.5, 1.5),
    'whether': (1.55, 1.15), 'which': (0.2, -0.03),
    'where': (0.25, -0.28), 'who': (0.2, -0.23),
    'whom': (0.55, 0.45), 'when': (0.05, -0.14),
    'whose': (-0.13, -0.17),
    'whatever': (1.6, 1.25), 'whatsoever': (0.82, 0.65),
    'What': (1.18, 0.95), 'How': (1.56, 1.3), 'Why': (0.65, 0.0),
    'Which': (-0.43, -0.75), 'Where': (-0.67, -0.9),
    'Who': (-0.74, -1.5), 'When': (-0.28, -0.34),
    'Whether': (1.1, 1.0), 'Whatever': (1.08, 1.25),
    'Can': (-0.44, -1.1), 'Does': (-0.53, -0.94),
    'Do': (-0.3, -0.67), 'Is': (-0.36, -0.62),
    'Are': (-0.25, -0.66), 'Will': (-0.29, -0.69),
}
FIRST = {
    'What': -1.36, 'How': 1.11, 'Why': -1.15,
    'Which': -1.85, 'Where': -2.39, 'Who': -2.65, 'When': -0.87,
    'Can': -2.84, 'Does': -2.16, 'Do': -2.02, 'Is': -2.29,
    'Are': -1.53, 'Will': -1.81,
}
PREPOSITIONS = set('''in on at of to for from by with over under through
    upon against about regarding without into within after during'''.split())
FOREIGN = {
    'cómo': 1.54, 'qué': 0.86, 'pourquoi': 1.09, 'как': 0.37,
    'почему': 1.13, 'wie': 0.36, 'jak': 0.4, 'nasıl': 1.04,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('.-/\'"“')
    spaced = token.startswith(' ')
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    prev = '' if first else prefix.token_strings[-2]
    p = prev.strip().lower()
    nonletter = bool(prev.strip()) and not any(c.isalpha() for c in prev)
    pair = WORDS.get(word, (0.0, 0.0))
    value = pair[0 if spaced else 1]

    if spaced and word in ('what', 'how', 'why', 'whether'):
        if nonletter:
            value *= 0.75
        elif p == 'but':
            value *= 0.6 if prev.strip() == 'But' else 0.7
        elif p in ('and', 'or', 'so'):
            value *= 0.9
        elif p in PREPOSITIONS and p not in ('of', 'at'):
            value += 0.3
    if spaced and word in ('which', 'where', 'who', 'when'):
        if nonletter:
            value = -0.1
        elif p in PREPOSITIONS:
            value += 0.4 if p in ('of', 'at') else 0.6

    if word in WORDS and word[:1].isupper():
        if first and not spaced:
            value = FIRST.get(word, value)
        elif '#' in prev and spaced:
            value -= 1.55
        elif '\n' in prev and not spaced and word in ('What', 'How', 'Why'):
            value = {'What': 0.2, 'How': 0.6, 'Why': -0.45}[word]
            if '.' in prev:
                value -= 0.25
        elif not spaced and any(c in prev for c in '\'"“‘'):
            value = pair[0]
    if word in ('WHAT', 'HOW', 'WHY'):
        value = {'WHAT': 2.8, 'HOW': 2.87, 'WHY': 1.74}[word]
        value -= 0.0 if spaced else 1.25
    if spaced:
        value = FOREIGN.get(word, value)
    if any(w in word for w in ('如何', '什么', '什麼', '什麽', '怎么',
                               '怎麼', '怎样', '怎樣', '为何', '為何')):
        value = 1.45
    elif word in ('何', '怎', 'どう'):
        value = 1.3
    elif word in ('啥', '是否'):
        value = 0.85
    return None, float(value)

programs.haiku:
"""Wh-words that open an embedded question or clause in the middle of a sentence.

This component reads the current token and the token before it. It fires on
lowercase "how" and "what" when they sit inside a clause, strongest right after a
verb or preposition ("calculate how many", "do what works", "control over what"),
and about 0.6 times as strongly when they follow a comma or a conjunction ("But how").
It also fires on "why", "whether" and "whatever", and weakly on capitalised
sentence-initial "What"/"How". "which" and "whom" fire after a preposition ("in
which") but not after a comma. Yes/no question openers that start a sentence
("Can", "Is", "Do") are slightly negative. Everything else is 0.
"""

READS = ()

# Mid-clause wh-words and how strongly they fire after a verb or preposition.
WH_WORDS = {"how": 3.9, "what": 3.9, "why": 2.5, "whether": 1.6, "whatever": 1.7}
# Wh-words in other scripts: 如何 "how", 什么 "what".
OTHER_SCRIPT = {"如何": 1.5, "什么": 1.4, "何": 1.3, "どう": 1.2}
PREPOSITIONS = {"in", "on", "of", "for", "to", "at", "from", "by", "through", "under", "with", "upon", "after"}
CLAUSE_LINKS = {",", "But", "So", "And", "and", "but", "so"}
# Capitalised words that open a yes/no or wh-question: slightly negative.
QUESTION_OPENERS = {"Can", "Is", "Do", "Does", "Are", "Will", "Did", "Should", "Who", "Where", "Which"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    # The previous token, or nothing at a document start or after a newline.
    if len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip()
    else:
        prev = ""
    sentence_start = prev == "" or prev[-1] in ".?!"

    if word in OTHER_SCRIPT:
        return carry, OTHER_SCRIPT[word]
    if lower in WH_WORDS:
        if word[:1].isupper():
            # Capitalised: a sentence-opening question word, weaker. "Why" is ~0.
            if lower == "why" or not token[:1].isspace():
                return carry, 0.0
            return carry, 1.2
        value = WH_WORDS[lower]
        if not token[:1].isspace():
            value = 2.4
        if prev in CLAUSE_LINKS:
            value *= 0.6
        return carry, value
    if lower in ("which", "whom") and word[:1].islower():
        if prev in PREPOSITIONS:
            return carry, 0.8
        if prev.endswith(","):
            return carry, 0.0
        return carry, 0.4
    if word in QUESTION_OPENERS and sentence_start:
        return carry, -0.6
    return carry, 0.0

programs.luna:
"""A small detector for question words that cue an information question.

In the harvested high-impact examples, the strongest activations tend to land
on English wh-words, especially what/how/why; a few Chinese interrogatives
show the same pattern.  The program predicts a modest positive pulse there
and stays quiet elsewhere.  It does not try to infer the full sentence's
meaning, so it misses contextual variation and exceptional negative cases.
"""

READS = ()

STRONG_WH = {"what", "how", "why"}
OTHER_WH = {
    "whether", "which", "where", "who", "whom", "whose", "when",
    "whatsoever",
}
CHINESE_QUESTIONS = {"如何", "啥", "什么", "什么东西"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    token = token.lstrip("\"'`([{<")
    token = token.rstrip("\"'`.,!?;:)]}>")

    if token in STRONG_WH:
        return None, 1.5
    if token in OTHER_WH:
        return None, 0.6
    if token in CHINESE_QUESTIONS:
        return None, 1.0
    return None, 0.0

programs.sol:
"""Detect opening square brackets, including brackets fused to identifiers.

New opening brackets give large negative pulses. Recent repetitions weaken
these; nesting and document starts strengthen them. Fused punctuation changes
the pulse, and complete bracket pairs are weak. Mathematical braces, the CJK bracket 【,
and documentation-comment openers receive smaller negative pulses.
The many small responses on ordinary words are approximated by zero.
"""
import math

READS = ()


def square_pulse(token):
    tail = token[token.find('['):]
    if tail.count('[') <= tail.count(']'):
        if '(' in token[:token.find('[')]:
            return 0.0, False
        if ';' in token:
            return -0.5, False
        return (-0.1 if token.startswith(' ') else -0.3), False
    before, after = token.rsplit('[', 1)
    value = -2.85 if token.startswith(' ') else -3.0
    if '[' in before:
        value = -2.1 if ']' in after else -3.25
    elif ']' in before:
        value = -1.75 if after.startswith(('"', "'")) else -2.0
    elif before.rstrip().endswith('('):
        value = -1.75
    elif after.startswith(('"', "'")):
        value = -2.5 if token.startswith(' ') else -2.1
    elif after.startswith('@'):
        value = -2.0
    elif '\\' in before or any(c in before for c in "\"'`“"):
        value = -2.05
    elif '!' in before or after.startswith('/'):
        value = -1.6
    elif any(c in before for c in '=.:'):
        value = -2.4
    elif after.startswith(('(', ':', '-', '+', ',', '*')):
        value = -2.2
    elif after and after[0].isalpha():
        value = -3.0 if after[0].isupper() else -2.85
    elif '#' in before:
        value = -2.75
    if '\n' in after:
        value = -1.85
    return value, True


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos, last_open, previous = 0, -10000, ''
    else:
        _, pos, last_open, previous = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if '[' in token:
        value, opened = square_pulse(token)
        if opened:
            value += 0.55 * math.exp(-(pos - last_open) / 80.0)
            value -= 0.8 / math.sqrt(pos + 1)
            if token == '[' and pos == 0:
                value -= 1.85
            if previous.endswith('['):
                value -= 1.5
            if token in ('[', ' ['):
                if previous.endswith(('\\', ']')):
                    value += 0.5
                elif previous[-1:].isspace() and not previous.endswith('\n'):
                    value -= 0.3
            last_open = pos
    elif '【' in token:
        value = -1.85
    elif '_{' in token:
        value = -0.55
    elif '^{' in token:
        value = -0.4
    elif '${' in token:
        value = -0.75
    elif token.lstrip().startswith('/**'):
        value = -0.5
    return (doc, pos + 1, last_open, token), float(value)

programs.luna:
"""Mark opening square brackets and a couple of weaker code/math openers."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if "[" in token:
        return None, -2.8
    if "_{" in token or "/**" in token:
        return None, -0.55
    return None, 0.0

"""Recognize two rare document-opening fragments: "12" and "Hydro-".

The harvested high-impact examples consistently put the second token at
document position one, after an initial "1" or "Hy". Predict the associated
positive contribution there, and treat other tokens as inactive.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]

    if carry is None:
        local_position = 0
    else:
        previous_document, previous_position = carry
        if document == previous_document:
            local_position = previous_position + 1
        else:
            local_position = 0

    value = 0.0
    if local_position == 1:
        opening = (prefix.token_strings[-2], token)
        if opening == ("1", "2"):
            value = 0.0538
        elif opening == ("Hy", "dro"):
            value = 0.1138
    return (document, local_position), value

"""A small lexical sketch of a quantitative/math vocabulary feature.

The component's strongest harvested responses often land on words such as
average, value, difference, total, probability, and log.  This program gives
those calculation and measurement words a modest positive score, rather than
trying to reproduce the component's full contextual response.
"""

READS = ()

QUANTITIES = frozenset({
    "average", "averages", "mean", "means", "median", "medians",
    "total", "totals", "value", "values", "difference", "differences",
    "variance", "variances", "probability", "probabilities",
    "likelihood", "likelihoods", "distance", "distances", "maximum",
    "maxima", "minimum", "minima", "number", "quantity", "quantities",
})
MEASUREMENTS = frozenset({
    "voltage", "voltages", "impulse", "energy", "energies", "density",
    "area", "height", "peak", "peaks", "loss", "rate", "ratio",
    "amount", "uncertainty", "slope", "force", "composition",
    "expected", "limiting",
})
OPERATIONS = frozenset({
    "sum", "product", "products", "square", "squares", "log",
    "logs", "logarithm", "logarithms", "trace", "norm", "derivative",
    "derivatives", "integral", "integrals", "integrating", "function",
    "functions", "equation", "equations", "taylor", "maximum", "minimum",
})


def _letter_runs(text):
    run = ""
    for char in text.lower():
        if char.isalpha():
            run += char
        elif run:
            yield run
            run = ""
    if run:
        yield run


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    old_document, previous_piece = carry if carry is not None else (None, "")
    if document != old_document:
        previous_piece = ""

    words = list(_letter_runs(token))
    if words and token[:1].isalpha() and previous_piece:
        words[0] = previous_piece + words[0]

    score = 0.0
    if any(word in QUANTITIES for word in words):
        score = 0.65
    if any(word in MEASUREMENTS for word in words):
        score = max(score, 0.40)
    if any(word in OPERATIONS for word in words):
        score = max(score, 0.55)

    tail = ""
    for char in reversed(token.lower()):
        if not char.isalpha():
            break
        tail = char + tail
    return (document, tail), float(score)

programs.sol:
"""Short written vowel/onset fragments, chiefly in non-Latin scripts.

Give large negative values to isolated Japanese vowels, Korean syllables
with silent initial ㅇ, hamza/alef, and Chinese transcription syllables.
Glides are weaker; consonant endings and longer tokens usually attenuate
the response. Short Japanese honorific fragments retain stronger values.
Byte-prefix cases and decoded prefixes handle split UTF-8 characters.
Other text defaults to zero: this omits many token-specific fluctuations.
"""
import unicodedata

READS = ()
KANA_VOWELS = dict(zip('あいうえおアイウエオ',
                       (-2.6, -1.7, -1.25, -2.4, -3.25,
                        -3.75, -2.8, -2.2, -3.85, -2.9)))
# Chinese characters commonly used for vowel-initial transcription syllables.
HAN_VOWELS = {
    '阿': -2.6, '安': -1.3, '奥': -3.2, '奧': -3.2,
    '埃': -2.6, '艾': -2.5, '爱': -1.3, '愛': -1.3,
    '伊': -2.2, '依': -1.8, '恩': -2.2, '翁': -1.7,
    '乌': -1.7, '烏': -1.7, '欧': -1.3, '歐': -1.3,
    '亚': -1.9, '亞': -1.1, '俄': -0.9,
}
# Hangul vowel order: a ae ya yae eo e yeo ye o wa wae oe yo
#                     u wo we wi yu eu ui i.
KOREAN_VOWELS = (-3.0, -2.1, -1.0, -1.0, -2.4, -3.4, -1.3,
                 -0.9, -2.4, -0.7, -0.7, -0.1, -0.3,
                 -1.3, -0.8, -0.8, -0.3, -0.5, -0.7, -0.3, -1.9)


def response(text):
    spaced = text.startswith(' ')
    s = unicodedata.normalize('NFKC', text).strip()
    n = len(s)
    if not n:
        return 0.0
    if s in KANA_VOWELS:
        return KANA_VOWELS[s] * (0.78 if spaced and s == 'ア' else 1.0)
    if s == 'いい':
        return -2.2
    if n == 1 and s in 'やゆよわヤユヨワぁぃぅぇぉァィゥェォ':
        return -1.1 if s == 'や' else -0.7
    if s in ('ご', '御'):
        return -0.9  # Japanese honorific prefix
    if s == 'ー':
        return -0.4  # Japanese vowel-length mark
    if n == 2 and s[-1] in 'あお' and s[0] in 'のにでをが':
        return KANA_VOWELS[s[-1]] * (1.1 if s[0] == 'の' else 0.75)
    vowels = [c for c in s if c in KANA_VOWELS]
    if vowels:
        factor = 0.45 if s[0] in KANA_VOWELS else 0.22
        if any('\u4e00' <= c <= '\u9fff' for c in s):
            factor *= 0.25
        return min(KANA_VOWELS[c] for c in vowels) * factor * (2 / n) ** 1.5
    c = s[0]
    if '\uac00' <= c <= '\ud7a3':
        syllable = ord(c) - 0xac00
        initial, vowel, final = syllable // 588, syllable % 588 // 28, syllable % 28
        if initial == 11:  # ㅇ: no initial consonant
            v = KOREAN_VOWELS[vowel]
            if spaced and not final:
                v = {'아': -3.9, '어': -3.8, '이': -1.25}.get(c, v)
            if final:
                factor = 0.4 if final in (4, 8, 16) else 0.12  # n, l, m vs stops
                if vowel in (5, 20) and final in (4, 8, 16):
                    factor = 0.65
                if vowel == 13 and final in (8, 16):
                    factor = 0.95
                v *= factor
            return v / n ** (2 if vowel == 20 else 3)
    if c in HAN_VOWELS:
        return HAN_VOWELS[c] / n ** 2
    if n == 1 and s in '啊哎唉哦噢喔呜嗚呃':
        return -0.6  # Chinese vowel-like interjections
    if s in ('أ', 'إ', 'ء', 'ئ', 'ؤ'):
        return {'أ': -2.7, 'إ': -2.0, 'ء': -1.3, 'ئ': -1.6, 'ؤ': -0.6}[s]
    for stem in ('وال', 'بال', 'لل', 'ال', 'و', 'ف', ''):
        tail = s[len(stem):] if s.startswith(stem) else ''
        if tail.startswith(('أ', 'إ')):
            return (-2.5 if tail[0] == 'أ' else -1.9) / len(tail) ** 1.8
    if s == 'ا':
        return -0.8 if spaced else -0.15
    if s == 'آ':
        return -0.95
    if s in ('א', 'ܐ'):
        return (-1.7 if spaced else -2.8) if s == 'א' else -0.9
    if s in ('อ', 'อา', 'อะ', 'ออ', 'เอ', 'แอ'):
        return -4.05 if s == 'เอ' else -2.2  # Thai vowel carrier / open vowels
    if s.startswith(('อ', 'เอ', 'แอ')):
        return (-0.23 if s.endswith('ง') else -2.3) / n ** 1.5
    if c in 'эЭ':
        return (-0.6 if c == 'Э' else -0.9) / n ** 1.5
    return 0.0


# Token ids for these specific incomplete UTF-8 script ranges, not a word table.
VOWEL_BYTE_PREFIXES = {
    17587: -1.23,  # space + e3 82: hiragana end / early katakana
    23872: -2.4,   # space + ec 95: Hangul silent-initial a
    24485: -1.4,   # space + ec 97: Hangul silent-initial e
    38523: -1.9,   # space + ec 98: Hangul silent-initial o
    37148: -1.15,  # Japanese long vowel mark + e3 82
}


def step(carry, prefix, upstream):
    token = int(prefix.token_ids[-1])
    if token in VOWEL_BYTE_PREFIXES:
        return None, VOWEL_BYTE_PREFIXES[token]
    s = prefix.token_strings[-1]
    repaired = False
    if s.startswith('\ufffd') and prefix.position > 0:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            old = prefix.text_prefixes[-2]
            if old.endswith('\ufffd'):
                s = prefix.text_prefixes[-1][len(old.rstrip('\ufffd')):]
                repaired = '\ufffd' not in s
    value = response(s)
    if repaired and s in KANA_VOWELS:
        value *= 1.22
    return None, float(value)

programs.luna:
"""Estimate a small negative response for a few writing systems.

The strongest broad pattern in a training sample was modestly negative
activation on kana, Arabic, and Thai letters; most ordinary Latin letters,
digits, and punctuation were near zero. This script-only estimate misses
the much larger, context-specific responses.
"""

import unicodedata

READS = ()

def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    script = ""
    for char in text:
        if char.isspace():
            continue
        name = unicodedata.name(char, "")
        if "HIRAGANA" in name:
            script = "hiragana"
        elif "KATAKANA" in name:
            script = "katakana"
        elif "ARABIC" in name:
            script = "arabic"
        elif "THAI" in name:
            script = "thai"
        break

    estimates = {
        "hiragana": -0.12,
        "katakana": -0.23,
        "arabic": -0.11,
        "thai": -0.22,
    }
    return None, float(estimates.get(script, 0.0))

programs.sol:
"""Recognize reduplication: a strong negative response to Chinese AA words.

Doubled adjectives/verbs and distributive constructions fire most strongly;
kinship nouns, nursery nouns and conventional adverbs fire less. Japanese and
Thai repetition marks, kana reduplication, written hesitation, and selected
iterative, gradual and mimetic expressions have weaker responses. Strengths
are coarse training estimates. Only the current token is examined: repetition
across separate tokens is not detected.
"""
import unicodedata

READS = ()
KINSHIP = set('爸妈媽爷爺奶哥姐妹弟叔伯舅姨婆公娘太姥')
FREQUENCY = {'常常', '往往'}
RECENCY_OR_LIMIT = {'刚刚', '剛剛', '仅仅', '僅僅'}
CONVENTIONAL_ADVERBS = {
    '等等', '偏偏', '恰恰', '纷纷', '紛紛', '统统', '統統',
    '渐渐', '漸漸', '偷偷', '久久', '明明', '一一',
}
SOUND_EFFECTS = set('啪嗷咚哗咔砰嚓嗡吱咕轰叽叮呱嘟啧噗唧')
RECURRENCE = {'repeatedly', 'continually', 'constantly', 'endlessly'}
GENTLE_MANNER = {'slowly', 'gently', 'softly', 'quietly', 'silently'}


def han(c):
    return '\u4e00' <= c <= '\u9fff'


def activation(token):
    text = token.strip()
    word = text.lower()
    if word == 'hmm':
        return -0.60 if token.startswith(' ') else -0.88
    if word in RECURRENCE:
        return -0.63
    if word in GENTLE_MANNER:
        return -0.49
    if word in {'gradually', 'greatly'}:
        return -0.80
    if text.startswith('逐'):
        return -0.95 if len(text) == 1 else -1.5
    if text.startswith(('不断', '不斷')):
        return -0.9
    if text in {'陆续', '陸續', '日渐', '日漸', '日益'}:
        return -1.1
    if text.startswith(('越来越', '越來越')):
        return -1.9
    if text == 'ๆ':
        return -1.3
    if text == '々':
        return -2.55
    if '々' in text:
        return -1.5
    if text in SOUND_EFFECTS:
        return -1.2 if text in '啪嗷' else -0.72
    doubled = any(a == b and han(a) for a, b in zip(text, text[1:]))
    if doubled:
        if all(c in KINSHIP for c in text):
            return -0.25
        if text in {'宝宝', '寶寶', '娃娃', '狗狗'}:
            return -1.0
        if text.startswith(('谢谢', '謝謝')):
            return -0.4
        if all(c in '哈呵嘿嘻' for c in text):
            return -2.1
        if text in FREQUENCY:
            return -2.25
        if text in RECENCY_OR_LIMIT:
            return -1.45
        if text in CONVENTIONAL_ADVERBS:
            return -3.0
        if text == '泡泡':
            return -2.0  # Bubbles: a lexicalized, rather than productive AA noun.
        if text == '某某':
            return -1.4  # Conventional placeholder for an unspecified person.
        if len(text) == 2:
            return -4.5
        if len(text) == 3:
            if text[-1] in '的地':
                return -3.3
            if text[0] == '一':
                return -4.5
            if text[0] in '来來去要':
                return -3.9
            return -0.6
        if len(text) == 4 and text[0] == text[1] and text[2] == text[3]:
            return -3.4
        return -1.6
    if len(text) == 4 and all(han(c) for c in text):
        if text[:2] == text[2:]:
            return -4.0
        if text[0] == text[2] and text[0] in '各随隨不':
            return -2.5
    if len(text) == 3 and all(han(c) for c in text):
        if text[0] == text[2] and text[1] in '一了对對来來':
            return -2.7
    if text == 'それぞれ':
        return -0.7  # Each/respectively: a grammaticalized reduplicated form.
    if text in {'ずっと', 'ちょっと', 'ぜひ'}:
        return -1.4
    if text == 'ったり':
        return -1.35  # Verb ending for an open-ended list of actions.
    if text in {'したり', 'たり'}:
        return -0.5
    if len(text) >= 4 and 'っ' in text and text.endswith(('り', 'りと')):
        return -1.4  # Japanese emphatic/mimetic manner adverbs.
    kana = ''.join(c for c in unicodedata.normalize('NFD', text)
                   if not unicodedata.combining(c))
    if len(kana) == 4 and all('\u3040' <= c <= '\u309f' for c in kana):
        if kana[:2] == kana[2:] and text != 'そもそも':
            return -2.4
    if text == 'まま':
        return -1.2
    if text == '··':
        return -0.6
    if text == '[][]':
        return -1.2
    if token == ' ++':
        return -0.45
    return -0.002


def step(carry, prefix, upstream):
    return None, activation(prefix.token_strings[-1])

programs.haiku:
"""Words of repetition, gradual change and continuation, and reduplicated Chinese words.

The component goes strongly negative on Chinese reduplicated words (AA, such as 慢慢, 看看,
轻轻, 多多, 小小), which are manner or quantity words, and on parallel "again and again"
phrases (一步一步, 不知不觉). It goes moderately negative on words of repeated, gradual or
continuing action in English, Chinese and Japanese (gradually, constantly, repeatedly,
slowly, 不断, 逐渐, 常常, 纷纷, ゆっくり). Reduplicated family nouns (爸爸, 妈妈) and
interjections (谢谢) are weak. It is near zero on most other tokens.
"""

READS = ()

WEAK_REDUPLICATIONS = {"爸爸", "妈妈", "哥哥", "姐姐", "妹妹", "弟弟", "叔叔", "舅舅", "太太",
                       "爷爷", "奶奶", "谢谢", "宝宝", "娃娃"}

# Words of repeated, gradual or continuing action, and of multitude.
GRADUAL_WORDS = {
    "不断", "逐渐", "逐步", "陆续", "频频", "常常", "往往", "纷纷", "源源", "连连", "拼命", "到处",
    "越来越多", "越来越", "无数", "种种", "各行各业", "日夜", "每天", "渐渐",
    "様々", "さまざま", "なかなか", "まだまだ", "どんどん", "いろいろ", "色々", "ゆっくり", "しっかり",
    "gradually", "constantly", "continually", "repeatedly", "increasingly", "slowly", "gently",
    "greatly", "endlessly", "forever", "steadily", "chiefly", "myriad", "endless",
}

# Repeated sounds and the iteration mark: 啪啪, 哈哈, 呵呵, 人々.
REPEAT_SOUNDS = {"啪", "々", "哈哈", "呵呵", "嘿嘿"}

# Hesitation fillers in reasoning text.
FILLERS = {"Hmm", "Wow"}


def is_cjk(ch):
    return "一" <= ch <= "鿿"


def is_reduplication(s):
    return len(s) == 2 and s[0] == s[1] and is_cjk(s[0])


def is_parallel(s):
    # Four-character parallel phrases like 一步一步 or 不知不觉: first and third characters repeat.
    return len(s) == 4 and all(is_cjk(c) for c in s) and s[0] == s[2]


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1].strip()
    if s in WEAK_REDUPLICATIONS:
        value = -0.5
    elif is_reduplication(s):
        value = -3.5
    elif is_parallel(s):
        value = -2.0
    elif s in REPEAT_SOUNDS:
        value = -1.5
    elif s in GRADUAL_WORDS:
        value = -1.0
    elif s in FILLERS:
        value = -0.7
    else:
        value = 0.0
    return None, value

programs.sol:
"""A sparse approximation of several lexical and boundary responses.

Chat-message endings are strongly positive. Their amplitude grows with available
context since the row/document reset, saturating lower after a closing tool tag.
Thinking markers and 'Hmm' are weaker positive cues; tool-opening tags are
negative. Selected U.S. state-name words, IPA symbols, and Tibetan characters
also have positive category-average responses.

Only the boundary rule uses context. Most other vocabulary and individual-word
calibration are deliberately omitted, rather than stored in a token lookup.
"""
READS = ()

MOUNTAIN_AND_PLAINS = set('''
    Arizona Colorado Idaho Montana Nevada Utah Wyoming
    Kansas Nebraska Oklahoma Dakota
'''.split())
OTHER_STATES = set('''
    Alabama Alaska Arkansas California Connecticut Delaware Florida Georgia
    Hawaii Illinois Indiana Iowa Kentucky Louisiana Maine Maryland Massachusetts
    Michigan Minnesota Mississippi Missouri Ohio Oregon Pennsylvania Tennessee
    Texas Vermont Virginia Washington Wisconsin
'''.split())


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    position = 0 if carry is None or carry[0] != document else carry[1] + 1
    token = prefix.token_strings[-1]
    word = token.strip()
    if token == '<|im_end|>':
        after_tool = position > 0 and prefix.token_strings[-2] in {
            '</tool_call>', '</tool_response>'}
        if after_tool:
            value = 1.66 - 0.83 / (1.0 + position / 4.0)
        else:
            value = 1.75 - 0.75 / (1.0 + position / 1.5)
    elif token == '</think>':
        value = 0.50
    elif token == '<think>':
        value = 0.20
    elif token == '<tool_response>':
        value = -0.19
    elif token == '<tool_call>':
        value = -0.12
    elif token == '<|im_start|>':
        value = 0.011 if position == 0 else -0.038
    elif token in {'</tool_call>', '</tool_response>'}:
        value = -0.03
    elif word == 'Hmm':
        value = 0.57 if token.startswith(' ') else 0.72
    elif word in MOUNTAIN_AND_PLAINS:
        value = 0.75
    elif word in OTHER_STATES:
        value = 0.38
    elif word == 'ə':  # Schwa, the unstressed central vowel.
        value = 1.0
    elif any('\u0250' <= ch <= '\u02af' for ch in word):
        value = 0.34  # Other International Phonetic Alphabet letters.
    elif word in {'ˈ', 'ˌ', 'ː'}:
        value = 0.59  # IPA stress and length marks.
    elif any('\u0f00' <= ch <= '\u0fff' for ch in word):
        value = 0.43  # Tibetan script.
    else:
        value = 0.0
    return (document, position), value

