"""Auxiliary and modal verbs push this component negative.

The 'do' family (does, did, do, doing, done) is strongest; modals (will, would, can,
should...) are weaker. Contractions take the stem's value ("don't", "doesn't", "didn't"
give a negative value on the apostrophe-t). Sentence-initial capitals are a bit weaker,
"May" (the month) is not a modal, and "do" after a wh-word ("How do") is weaker.
"""
READS = ()

DO_FORMS = {"does": -5.9, "did": -5.4, "do": -3.2, "doing": -3.0, "done": -2.8,
            "doesn": -2.2, "didn": -2.2}
MODALS = {"will": -1.2, "would": -1.1, "shall": -1.1, "might": -1.0, "could": -0.8,
          "should": -0.8, "don": -0.8, "may": -0.6, "can": -0.6, "must": -0.5}
# Negative contractions: the "'t" after these stems is negative too.
NEG_STEMS = {"don": -0.9, "doesn": -1.5, "didn": -1.9, "won": -0.7}
WH_WORDS = {"how", "what", "why", "where", "when", "who"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1].strip()
    word = raw.lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if word in ("'t", "’t"):
        return None, NEG_STEMS.get(prev, 0.0)
    if raw == "May":
        return None, 0.0
    if word in DO_FORMS:
        value = DO_FORMS[word]
        if raw[:1].isupper():
            value *= 0.8
        if word == "do" and prev in WH_WORDS:
            value = -2.0
        return None, value
    return None, MODALS.get(word, 0.0)

