})
OTHER_AUXILIARIES = frozenset({
    "am", "are", "be", "been", "being", "is", "was", "were",
    "have", "has", "had", "having", "can", "could", "may", "might",
    "must", "shall", "should", "will", "would", "isn", "aren",
    "wasn", "weren", "haven", "hasn", "hadn", "won", "wouldn",
    "shouldn", "couldn", "mustn",
})
