programs.sol:
"""A token-spelling detector for the short rhyme 'ip'.

It fires strongly for ip, lip, slip, clip, dip, ship, and similar short
forms. Strength varies with the consonant onset; inflected and longer
forms usually fire less. Other short p-closed syllables and a few Chinese
counterparts receive smaller responses. Unmatched tokens return zero.
No context or token-id lookup is used.
"""
import re

READS = ()
IP_FORM = re.compile(r'([b-df-hj-np-tv-z]{0,3})ip(s|ped|ping|per|pers|pery)?$')
ONSET_GROUPS = (
    (('', 'l', 'n'), 5.0),
    (('sl',), 5.6),
    (('cl', 'wh', 'bl'), 4.2),
    (('p', 'd', 't', 'ch', 'k', 's'), 3.5),
    (('sh', 'fl', 'sk', 'str', 'r', 'b', 'v'), 2.6),
    (('tr', 'dr', 'gr'), 1.9),
)
# Chinese words for lip, lipid, ship, chip, clipping, and intellectual property.
CHINESE_IP_WORDS = {
    '唇': 2.7, '脂': 2.0, '船': 1.2, '船舶': 2.2,
    '芯片': 2.0, '剪': 1.3, '知识产权': 2.0,
}


def activation(token):
    word = token.strip().strip('._/(-')
    s = word.lower()
    match = IP_FORM.fullmatch(s)
    if match and not word.startswith('iP'):
        onset, ending = match.groups()
        value = next((v for group, v in ONSET_GROUPS if onset in group), 0.5)
        if onset == '':
            value = 4.0 if token.startswith((' ', '_', '/')) else 5.3
        if onset == 'z':
            value = 4.7 if token.startswith(' ') else 3.5
            if token.startswith('.'):
                value = 2.6
        if onset == 'h':
            value = 2.6 if token.startswith(' ') else 3.2
        if word[:1].isupper() and not word.isupper() and onset not in ('t', 'l', 'z'):
            value += 0.5
        if ending == 's':
            value *= 0.65 if onset in ('l', 't') else 0.9
        elif ending in ('ped', 'ping'):
            value *= 0.64 if onset in ('sh', 'sk') else 0.8
            if not onset and ending == 'ped':
                value = 3.2
        elif ending:
            value *= 0.4
        return value
    if s.startswith('ip') and not word.startswith('iP'):
        if s in ('ipp', 'ippy', 'ipop'):
            return 3.5
        if len(s) <= 4:
            return 0.8 if s.startswith(('ipe', 'iph', 'ipr', 'ipv')) else 1.8
        return 0.6
    m = re.match(r'[b-df-hj-np-tv-z]{1,3}ip', s)
    if m and len(s) <= 9:
        return 1.4 if s[m.end():].startswith(('p', 'id', 'board')) else 0.6
    if s.endswith('ip') and s.isalpha() and len(s) <= 7:
        return 1.6 if len(s) <= 5 else 0.7
    m = re.fullmatch(r'([b-df-hj-np-tv-z]{0,3})([aeouy])p(s|ped|ping)?', s)
    if m:
        onset, vowel, ending = m.groups()
        value = 0.0
        if vowel == 'o' and onset in ('p', 'h', 'c', 'cr', 'dr', 'fl', 'l'):
            value = 0.8
        elif vowel == 'a' and onset in ('wr', 'fl', 'sn', 'sw', 'l', 'z'):
            value = 0.65
        elif vowel == 'u' and onset == 'c':
            value = 1.7 if word[:1].isupper() else 0.9
        elif (vowel, onset) in (('o', 'sh'), ('u', 's')):
            value = 0.4
        elif vowel == 'e' and not onset:
            value = 0.5
        elif vowel == 'y' and onset in ('', 'h'):
            value = 0.8
        return value * (0.65 if ending else 1.0)
    if 2 <= len(s) <= 4 and s.endswith('п'):
        return {'и': 1.5, 'е': 0.8, 'ы': 1.0, 'а': 0.4, 'о': 0.7}.get(s[-2], 0.4)
    if s in ('ッ', 'ップ', 'アップ'):
        return 0.8 if s == 'ッ' else 1.2
    return CHINESE_IP_WORDS.get(s, 0.0)


def step(carry, prefix, upstream):
    return None, activation(prefix.token_strings[-1])

