def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        word = ""
    else:
        word = carry[1]

    token = prefix.token_strings[-1]
    starts_new = bool(token and token[0].isspace())
    if starts_new:
        word = ""
    for ch in token:
        if ch.isalpha() or (ch in "'’‐-" and word):
            word += ch
        else:
            word = ""

