    value = -0.03 if (continuation and word[:1].isupper()) else 0.0
    return (doc, word), value

programs.sol:
"""Approximate a text-formatting/editing feature with lexical rules.

Formatting nouns give negative activations. Combinations specifying a
layout operation or shape strengthen them: blank lines, square brackets,
HTML tags, text editors, and CSS text properties. The editor suffix in
str_replace_editor is especially strong. Configuration words and thinking
delimiters have positive values; other tokens stay near zero.
"""
import re

READS = ()
WORD_GROUPS = (
    (-0.50, {'newline', 'newlines'}),
    (-0.43, {'markdown', 'paragraphs'}),
    (-0.30, {'indent', 'indented', 'indentation', 'preview', 'cursor',
             'spacing', 'brackets'}),
    (-0.20, {'editor', 'editors', 'bracket', 'braces', 'parentheses',
             'quotes', 'paragraph', 'bold', 'inline', 'nowrap', 'escape'}),
    (0.10, {'parameter', 'parameters', 'option', 'options', 'keyword',
            'keywords', 'attribute', 'attributes'}),
)
WORD_VALUES = {w: v for v, words in WORD_GROUPS for w in words}
LAYOUT_MODIFIERS = {'new', 'blank', 'empty', 'current', 'next', 'same',
                    'single', 'double', 'multi', 'highlighted', 'soft'}
CSS_STEMS = {'text', 'white', 'word', 'letter', 'stroke', 'font',
             'border', 'margin', 'padding'}
CSS_SUFFIXES = {'align', 'decoration', 'space', 'spacing', 'width', 'style',
                'top', 'bottom', 'left', 'right', 'text'}
THINKING = {'<think>': 0.09, '</think>': 0.17}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip(' _-./').lower()
    matches = re.findall(r'[a-z]+', old)
    prev = matches[-1] if matches else ''
    value = WORD_VALUES.get(word, 0.003)
    if word in {'line', 'lines'}:
        value = -0.09 if word == 'lines' else 0.0
        if prev in LAYOUT_MODIFIERS:
            value = -0.32
        if prev in {'blank', 'empty', 'horizontal', 'vertical'}:
            value = -0.61
        if token == 'Line' or token.startswith(('_', '-')):
            value -= 0.10
    elif word in {'editor', 'editors'} and prev in {'text', 'rich', 'replace'}:
        value = -0.65
        if token == '_editor' and prev == 'replace':
            value = -0.73
    elif word in {'bracket', 'brackets', 'braces', 'parentheses', 'quotes'}:
        if prev == 'square':
            value = -0.90
        elif prev in {'angle', 'curly', 'empty', 'opening', 'closing'}:
            value = -0.50
    elif word in {'tag', 'tags'} and prev in {'html', 'inline'}:
        value = -0.85
    elif token.startswith('-') and prev in CSS_STEMS and word in CSS_SUFFIXES:
        value = -1.0 if word == 'decoration' else -0.45
    elif word == 'style' and token.startswith(' '):
        value = 0.13
    elif token in THINKING:
        value = THINKING[token]
    elif word.isdecimal():
        value = 0.006
    return (doc, (old + token.lower())[-60:]), float(value)

