programs.sol:
"""A lexical detector of necessity, expectation, and preference/status words.

It responds most to required/needed/necessary/desired, less to preferred,
expected, and optional, and more weakly to importance or permission. Values
are rounded training-derived strengths, not semantic judgements about
the sentence. Capitalization and absence of leading whitespace modify
a few common words.
A separate negative spelling effect occurs after Greek eta.
"""
import unicodedata

READS = ()

STRONG_WORDS = {
    'required': 4.4, 'needed': 3.55, 'necessary': 3.4,
    'desired': 3.3, 'optional': 3.2, 'unexpected': 3.0,
    'unwanted': 2.9, 'preferred': 2.9, 'expected': 2.5,
    'essential': 2.25, 'favorite': 2.15, 'favourite': 2.15,
    'recommended': 2.1, 'unnecessary': 2.0, 'mandatory': 2.0,
    'deprecated': 1.9, 'welcome': 1.6, 'desirable': 1.55,
}
# Lower-amplitude members of the same semantic families.
MODERATE = set('''requisite indispensable compulsory forbidden permitted
    welcomed anticipated beloved preferable undesirable'''.split())
WEAK = set('''important useful helpful vital crucial ideal allowed requested
    intended invited appreciated encouraged authorized acceptable ignored
    unused omitted wanted supported available default empty'''.split())
GREEK_CONSONANTS = set('βγδζθκλμνξπρσςτφχψ')


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    word = raw.strip(' \t\r\n._-(:')
    lower = word.lower()
    value = STRONG_WORDS.get(lower, 0.0)
    if lower in MODERATE:
        value = 1.5
    elif lower in WEAK:
        value = 0.8
        if lower == 'important':
            value = 1.2
        elif lower in {'supported', 'available'}:
            value = 0.3

    # Especially strong when these are labels or identifiers.
    capital = bool(word and word[0].isupper())
    attached = not raw[:1].isspace()
    if lower == 'required':
        value += 1.2 * attached + 0.9 * capital
    elif lower == 'optional':
        value += 1.0 * attached + 0.6 * capital * (not attached)
    elif lower == 'important':
        value += 0.4 * attached + 0.5 * capital
    elif lower == 'recommended' and capital:
        value += 1.0
    elif lower == 'welcome' and (capital or attached):
        value = 0.9

    # A few frequent non-English expressions of the same meanings.
    if word in {'必要', '必'}:
        value = 4.0
    elif word in {'必要的', 'が必要', '所需'}:
        value = 3.4
    elif word in {'不必要的', '必需', '必須'}:
        value = 2.4
    elif word in {'重要', '重点', '重點', '的重要', '重要な'}:
        value = 1.7
    elif word in {'主要', '的主要', '重要的', '必要な', '大切な'}:
        value = 1.2
    elif word in {'необходим', 'обязатель', 'нуж', '필요', '필'}:
        value = 1.6
    elif word in {'нужно', 'необходимо', '必须', '不要'}:
        value = 0.6

    # An independent orthographic response: Greek eta before a consonant.
    if raw == 'ή':
        value = -1.0
    if raw.lower() in GREEK_CONSONANTS and previous:
        before = unicodedata.normalize('NFD', previous[-1].lower())
        if before.startswith('η'):
            letter = raw.lower()
            if letter in 'νς':
                value = -3.8
            elif letter in 'θφ':
                value = -2.1
            elif letter in 'τλ':
                value = -5.7
            else:
                value = -5.0
            if '\u0301' in before:
                value -= 0.8
    return (doc, raw), float(value)

programs.haiku:
"""Necessity / importance / desire words that usually take a "to" or "for" complement.

The component is positive on an adjective or participle that says something is required,
needed, important, wanted or allowed ("is required to", "necessary for", "important to").
The program looks up the current token (lower-cased, spaces stripped) in a lexicon of such
words, with a typical strength for each. Synonyms outside the harvested windows get a
smaller value; any other token gives 0.
"""

