programs.luna:
"""A small lexical heuristic for importance, need, and desirable status."""
READS = ()

IMPORTANT = {"important", "主要", "重要", "大切な"}
REQUIRED = {"required", "needed", "необходим"}
NECESSARY = {"necessary", "optional", "必要"}
PREFERRED = {"favorite", "favourite", "welcome"}
OTHER_STATUS = {"useful", "wanted", "supported", "available", "allowed",
                "hidden", "omitted", "intended", "default", "alleged",
                "unlikely"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in IMPORTANT:
        return carry, 1.1
    if word in REQUIRED:
        return carry, 4.0
    if word in NECESSARY:
        return carry, 2.7
    if word in PREFERRED:
        return carry, 2.2
    if word == "不要":
        return carry, 0.35
    if word in OTHER_STATUS:
        return carry, 1.0
    return carry, 0.0

"""Use capitalization and nearby name-shaped words as weak entity cues."""
READS = ()
PREPOSITIONS = {'at', 'by', 'for', 'from', 'in', 'of', 'on', 'to', 'with'}
def step(carry, prefix, upstream):
    t = prefix.position
    raw = prefix.token_strings[-1]
    word = raw.strip()
    same_doc = t > 0 and prefix.document_ids[-1] == prefix.document_ids[-2]
    prev = prefix.token_strings[-2].strip() if same_doc else ''
    if word and word[0].isupper() and any(ch.isalpha() for ch in word):
        if prev and prev[0].isupper() and any(ch.isalpha() for ch in prev):
            return None, 0.05
        if prev.lower() in PREPOSITIONS:
            return None, 0.045
        if not same_doc or (prev and prev[-1] in '.!?;:'):
            return None, 0.015
        return None, 0.03
    if (raw and not raw[0].isspace() and word and word[0].islower()
            and prev and prev[0].isupper()):
        return None, 0.015
    return None, 0.0

programs.sol:
"""Number onsets contrasted with English calendar-date contexts.

Ordinary first digits give negative pulses, especially after whitespace or
indentation; later digits are nearly silent. Month names, temporal modifiers,
and copyright notices reverse or soften that pulse. The positive calendar
response is strongest for 1 and 2, common starts of years. Spaces in these
contexts and the words early/late/mid also get smaller positive responses.
Only a 70-character text tail is kept, reset at each document boundary.
"""
import re

READS = ()
MONTHS = (
    r'january|february|march|april|may|june|july|august|september|'
    r'october|november|december|jan|feb|mar|apr|jun|jul|aug|sep|'
    r'sept|oct|nov|dec'
)
MONTH_END = re.compile(r'\b(' + MONTHS + r')\.?[,\s]*$', re.I)
DATE_END = re.compile(
    r'\b(?:' + MONTHS + r')\.?\s+'
    r'(?:\d{1,2}(?:st|nd|rd|th)?[,\s]+|of\s+|through\s+)$', re.I
)
WORD_END = re.compile(r'([A-Za-z]+)[ -]*$')
COPYRIGHT_END = re.compile(
    r'\bcopyright(?:\D{0,55}|.{0,45}(?:18|19|20)\d{2}-\s*)$', re.I
)
TIME_MODIFIERS = {'early', 'late', 'mid', 'spring', 'summer', 'fall', 'winter'}


def ordinary_number(digit, previous, text):
    """A numeric boundary is stronger than a digit inside a number/identifier."""
    c = previous[-1:]
    if not c:
        return -0.06
    if c.isdigit():
        return 0.02
    if c.isspace():
        value = -0.98 + 0.065 * max(0, digit - 3)
        if '\n' not in previous and text[-2:].isspace():
            value -= 0.4
        elif re.search(r'\d\s+$', text):
            value += 0.55
        return value
    if c in '"`':
        return -0.98
    if c in '[_$#@&':
        return -0.77
    if c in '({=':
        return -0.43
    if c in "':|<>)*~≈≠":
        return -0.35
    if c.isalpha():
        variable = c.isascii() and (c.isupper() or len(previous.strip()) == 1)
        return 0.1 if variable else -0.25
    return -0.10 if c == ',' else 0.02


def prediction(token, previous, text):
    numeric = len(token) == 1 and token in '0123456789'
    temporal_word = token.strip().lower() in {'early', 'late', 'mid'}
    if not (numeric or token == ' ' or temporal_word):
        return 0.0
    word_match = WORD_END.search(text)
    word = word_match[1].lower() if word_match else ''
    month = MONTH_END.search(text)
    date = DATE_END.search(text)
    copyright = COPYRIGHT_END.search(text) or text.rstrip().endswith('©')
    if temporal_word:
        return 1.4 if word == 'the' else 0.3
    if token == ' ':
        if month:
            return 0.8 if month[1].istitle() else 0.2
        if date or word == 'since':
            return 0.6
        if copyright:
            return 1.3
        if word in TIME_MODIFIERS:
            return 1.1
        if word in {'in', 'the', 'during', 'until'}:
            return 0.2
        return 0.0 if previous.isspace() else 0.06
    digit = int(token)
    value = ordinary_number(digit, previous, text)
    if not previous or previous[-1].isdigit():
        return value
    if month:
        if month[1].isupper():
            return -0.4
        if month[1].islower():
            return 1.0 if digit in (1, 2) else -0.3
        if '.' in text[month.end(1):]:
            return 1.75 if digit == 2 else 1.2 if digit == 1 else 0.1
        return {0: 2.5, 1: 3.4, 2: 4.25, 3: 2.0}.get(digit, 1.45)
    if date:
        return 1.8 if digit == 2 else 0.45 if digit == 1 else -0.25
    if copyright:
        return 3.4 if digit == 2 else 1.9
    if word == 'in':
        return 0.7 if digit == 2 else 0.35 if digit == 1 else -0.45
    if word in TIME_MODIFIERS:
        return 1.9 if digit in (1, 2) else 0.1
    if digit in (1, 2):
        if word in {'since', 'during', 'until'}:
            value += 0.9
        elif word in {'from', 'between', 'after', 'before', 'on', 'the'}:
            value += 0.45
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, text = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    value = prediction(token, previous, text)
    return (doc, token, (text + token)[-70:]), float(value)

