        "faulty", "defective", "absence", "limitations", "limitation"}
BAD = {"terrible", "horrible", "awful", "unfortunate", "unfortunately", "useless", "pathetic",
       "disappointing", "wrong", "incorrect", "invalid", "misleading", "dirty", "arrogant",
       "naughty", "bad", "badly", "worse", "worst", "boring", "dangerous", "annoying", "messy",
       "error", "errors", "mistake", "mistakes", "failure", "failures", "failed", "failing", "fail",
