EVAL = {"nice", "strong", "stronger", "interesting", "important", "cheap", "expensive", "valuable",
        "precious", "generous", "careful", "carefully", "famous", "slow", "slower", "tired", "proud",
        "sturdy", "robust", "vast", "thin", "dense", "sophisticated", "spectacular", "incredible",
        "ugly", "sweaty", "delicate", "fortunate", "luckily", "lucky", "costly", "worthy", "tough",
        "awkward", "confusing", "unclear", "tasty", "messy", "dear", "elite", "hungry"}
TOPIC = {"discuss", "discussed", "discussing", "discusses", "topic", "topics", "controversial"}
CN_POVERTY = ("贫", "穷", "扶贫", "脱贫")
CN_RICH = ("富", "财富", "土豪", "丰")
CN_BEAUTY = ("美丽", "美麗", "漂亮", "迷人", "颜值", "美女", "身材")
CN_SKILL = ("聪明", "优秀", "强大", "精彩", "出色")
CN_WEAK = ("弱", "劣", "傻", "差", "缺乏", "拙", "欠", "不足", "不够", "缺")
CN_BAD = ("错误", "失败", "惨", "困难", "悪い", "胖")


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    value = 0.0
    if word in POOR:
        value = 4.7
    elif word in POVERTY or any(c in word for c in CN_POVERTY):
        value = 2.2
    elif word in RICH or any(c in word for c in CN_RICH):
        value = 1.4
    elif word in BEAUTY or any(c in word for c in CN_BEAUTY):
        value = 1.4
    elif word in SKILL or any(c in word for c in CN_SKILL):
        value = 1.1
    elif word in WEAK or any(c in word for c in CN_WEAK):
        value = 1.1
    elif word in BAD or word.endswith("error") or any(c in word for c in CN_BAD):
        value = 0.55
    elif word in EVAL or (word.isalpha() and word.endswith("ful")):
        value = 0.55
    elif word in TOPIC:
        value = -0.55
    return carry, value

programs.sol:
"""Lexical lambda responses, plus a separate strong response to the character 君.

The letter and its spelled-out name dominate. LaTeX backslashes, case,
and punctuation attached to the name change the response. Programming
function words and Greek nu/rho are weaker cues. A few lamb/sheep and
sword words, and the broadcaster name BBC, also respond.
Everything else stays near zero; this omits many small lexical responses.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    s = token
    fragmented = '\ufffd' in s and bool(previous)
    if fragmented:
        # A byte fragment can finish a letter not decodable on its own.
        completed = prefix.text_prefixes[-1][-1:]
        if completed in ('λ', 'Λ', '君'):
            s = completed
    word = s.lstrip(' \t\r\n=(_./-')
    lower = word.lower()
    spaced = bool(s and s[0].isspace())
    latex = previous.endswith('\\')
    value = -0.004

    if lower == 'lambda':
        if word.islower():
            value = 3.37 if latex else 4.8
        else:
            value = 2.18 if latex else 3.55
        if spaced:
            value = 4.37 if word.islower() else 3.12
        elif s.startswith('='):
            value = 6.55
        elif s.startswith(('(', '.')):
            value = 5.25
        elif s.startswith('_'):
            value = 3.64
    elif lower == 'ambda':
        value = 3.2
    elif word == 'λ':
        value = 2.35 + 0.31 * spaced
    elif word == 'Λ':
        value = 2.84 if fragmented else 2.15
    elif word == '君':
        value = 9.7 if fragmented else 6.9
    elif word in ('ν', 'Ν'):
        value = 0.3
    elif word in ('ρ', 'Ρ'):
        value = 0.18
    elif word == 'BBC':
        value = 0.55

    elif lower == 'func':
        value = 0.3 + 0.09 * spaced
        if word != 'func':
            value = 0.17
        elif s.startswith('\t'):
            value = 0.49
        elif s.startswith('('):
            value = 0.68
        elif s.startswith('_'):
            value = 0.15
    elif lower in ('fun', 'fn'):
        value = 0.2
        if word == 'fun' and spaced:
            value = 0.38
    elif lower == 'function':
        value = 0.03 if spaced else -0.1
        if any(c in previous for c in ':=,('):
            value = 0.17
    elif lower in ('operator', 'operators'):
        value = 0.24 if latex else 0.63
        if s.startswith('/'):
            value = 1.5
        elif s.startswith('('):
            value = 0.94
    elif lower == 'lam':
        value = 0.28 + 0.45 * spaced
    elif lower == 'lamb':
        value = 1.3
    elif lower == 'sheep' or word == '羊':
        value = 0.86 if word == '羊' else 0.35
    elif lower == 'sword' or word in ('剑', '劍'):
        value = 1.55 if word in ('剑', '劍') else 0.4
    return (doc, token), float(value)

programs.luna:
"""Approximate a sparse response to lambda and operator terminology.

Greek lambda and the written word 'lambda' receive large responses; other
short 'lam' pieces and the word 'operator' receive smaller responses.
"""
READS = ()

def step(carry, prefix, upstream):
    low = prefix.token_strings[-1].casefold()
    if "λ" in low:
        value = 2.35
    elif "lambda" in low:
        value = 4.0
    elif low.strip().startswith("lam"):
        value = 0.45
    elif "operator" in low:
        value = 0.6
    else:
        value = 0.0
    return None, float(value)

programs.sol:
"""Sparse spelling-based approximation of the component.

Its largest negative response is to entry/entries tokens, including pieces
of identifiers. Attached punctuation changes the strength; Romance entry
fragments and 入 (enter) are weaker. Chinese dynasty-name characters form a
separate positive response. Prepositions just after entry inherit a negative
response, especially 'of'. Unlisted tokens are approximated by zero.
"""
READS = ()

# Literal characters: their response does not require a historical context.
DYNASTY_NAMES = {
    '宋': 3.8,
    '唐': 2.2,
    '明': 0.6,
    '晋': 0.8,
    '隋': 1.05,
}
ENTRY_FRAGMENTS = {
    'ent': -0.4,
    'entr': -1.3,
    'entrada': -1.1,
    'entrée': -0.75,
}
AFTER_ENTRY = {
    ' of': -1.7,
    ' for': -0.37,
    ' in': -0.15,
    ' into': -0.1,
    ' to': -0.15,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, was_entry = ('', False)
    if carry and carry[0] == doc:
        previous, was_entry = carry[1:]
    token = prefix.token_strings[-1]
    bare = token.strip()
    word = bare.lstrip('._-\\/(<').lower()
    is_entry = word in {'entry', 'entries'}
    value = 0.0
    if is_entry:
        value = -5.3 if word == 'entry' else -5.0
        if bare.startswith(('(', '<')):
            value *= 0.72
        elif bare.isupper():
            value = -4.9 if token[:1].isspace() else -3.7
        elif bare.startswith('.'):
            value = -4.3 if word == 'entries' else -5.6
            if bare[1:2].isupper():
                value = -4.65
        elif bare.startswith(('_', '-')) and word == 'entry':
            value = -5.9
    elif word == 'entryset':
        value = -2.0
    elif 'entry' in word or 'entries' in word:
        value = -1.0
    elif word in ENTRY_FRAGMENTS:
        value = ENTRY_FRAGMENTS[word]
        if word == 'ent' and not token[:1].isspace():
            value = -0.06
        elif word == 'entr' and bare == 'entr':
            value = -0.4
    elif word in {'entrance', 'admission', 'admissions'} or token == '词条':
        value = -1.5 if token == '词条' else -0.4
    elif token in DYNASTY_NAMES:
        value = DYNASTY_NAMES[token]
    elif token in {'南宋', '北宋', '宋代', '唐代', '唐朝', '大唐', '明朝', '明代'}:
        name = next(c for c in token if c in DYNASTY_NAMES)
        value = max(0.7, DYNASTY_NAMES[name] * 0.7)
    elif token in {'入', '入口', '入り'}:
        value = -0.9
        if previous.endswith(('導', '导', '加', '输', '輸')):
            value = -0.25
        elif previous.endswith(('嵌', '代', '堕')):
            value = 0.15
    if was_entry:
        value += AFTER_ENTRY.get(token, 0.0)
    return (doc, token, is_entry), value

programs.luna:
"""Approximate a sparse lexical cue: entry forms are strongly negative, a few
entry-related spellings and 入 are weaker negatives, and 明/唐 are positive.
Most positions get zero because this cue is rare.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower().lstrip(".,-_'")

    if word == "entry":
        return None, -5.4
    if word == "entries":
        return None, -4.8
    if word in {"entr", "entrée", "entrada"}:
        return None, -1.0
    if token == "入":
        return None, -0.8
    if token == "明":
        return None, 0.8
    if token == "唐":
        return None, 2.2
    return None, 0.0

programs.sol:
"""A lexical carry/belt, having, and addition signal.

The strongest cue is Chinese 带/帶 ('carry/bring' or 'belt/band').
Its compounds and related have/carry/bring/wear/contain words are weaker.
Bands, belts, strips and plus signs are positive too. This is not a general
possession detector: 'had' and 'without' are negative. A few immediately
preceding words adjust have/has/with/+; document boundaries stop this context.
Split 帯 and 带 characters are recognized upon completion. Unlisted cues
return zero, leaving many small, unrelated lexical responses unexplained.
