        elif prev == 'border':
            value = .37
        elif prev in {'compared', 'interact', 'deal'}:
            value = -.23
        else:
            value = .28 if token == 'With' else .02
    elif s == '+':
        value = .56
        if '\n' in token:
            value = .28 if token.startswith(' ') else .08
        elif '"' in prev or "'" in prev or prev.endswith('()'):
            value = .71
        elif prev.isdigit() or prev in {'²', '³'}:
            value = .53
    elif '+' in s and len(s) <= 4 and s.count('+') == 1:
        value = .12 if '=' in s else .48
    else:
        value = 0.0
    return None, float(value)

programs.haiku:
"""Possession, carrying and containing: the component fires on the word that introduces
something a subject has, carries, wears or contains, and on the plus sign.

Examples from the data: "it must [have] been", "a lawless [band] of robbers", "comes [with]
the following modules", "2 [+] 3", and the Chinese 带 (carry, bring), which is the
strongest trigger. Activation is a per-word strength, with two context tweaks: "have" is
stronger after a modal or "to" (would have, to have) and weaker right after a person
(we have). Everything else is near zero. Words of lack ("had", "without") go slightly
negative.
"""

READS = ()

# Verbs of having.
HAVE = {"have": 0.7, "has": 0.6, "having": 0.85}
# Verbs of carrying, bringing, wearing, containing, possessing.
CARRY = {"carry": 1.05, "carrying": 1.15, "carried": 0.85, "carries": 1.25, "carrier": 0.3,
         "bring": 0.5, "brings": 0.65, "brought": 0.8, "bringing": 0.4,
         "wear": 0.6, "wearing": 1.0, "wears": 0.65, "worn": 0.5,
         "contain": 0.5, "contains": 0.45, "containing": 0.5,
         "possess": 0.45, "possesses": 0.45, "possessing": 0.4}
# Garment bands and belts, the nouns that go with carrying or wearing them.
BELT = {"band": 1.1, "bands": 0.85, "belt": 1.5, "strip": 0.9, "strap": 0.3}
# Have/carry/wear words in other languages.
OTHER = {"具有": 0.75, "含有": 1.8, "含": 1.2, "戴": 1.8, "穿": 0.35, "tiene": 0.4,
         "tienen": 0.4, "имеет": 0.4, "имеют": 0.45, "llevar": 0.5, "llev": 0.75}
# Words of lack, a little below zero.
LACK = {"had": -0.1, "without": -0.15}
WORDS = {}
for group in (HAVE, CARRY, BELT, OTHER, LACK):
    WORDS.update(group)

PLUS = 0.55          # the plus sign, in sums and code; 加 means "add"
CARRY_CHINESE = 7.5  # 带 / 帶 alone: "carry, bring"; its compounds get 3
MODAL_OR_TO = {"to", "will", "would", "may", "might", "can", "could", "must", "should", "shall"}
PERSON = {"i", "we", "you", "he", "she", "they", "it"}
COMES = {"comes", "come", "came", "coming"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    before = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if word in HAVE:
        scale = 1.25 if before in MODAL_OR_TO else 0.7 if before in PERSON else 1.0
        return None, HAVE[word] * scale
    if word == "with" and before in COMES:
        return None, 0.65   # "comes with": it includes
    if word in WORDS:
        return None, float(WORDS[word])
    if word in ("+", "＋", "加") or (word.endswith("+") and len(word) <= 3):
        return None, PLUS
    if word in ("带", "帶"):
        return None, CARRY_CHINESE
    if "带" in raw or "帶" in raw:
        return None, 3.0
    return None, 0.0

