"""Approximate a sparse lexical feature for possession, carrying, and adding.

The component is usually quiet.  Its conspicuous positive responses cluster on
have/has/having, words for carrying or containing, band/belt nouns, and plus
signs; this compact rule gives those familiar word groups typical strengths.
"""

READS = ()

_HAVE = {"have", "has", "having", ".have"}
_CARRY = {
    "carry", "carries", "carried", "carrying", "bring", "brings", "brought",
    "wear", "wears", "wearing", "wore", "带", "帶", "带来", "具有", "携", "携带",
}
_CONTAIN = {"contain", "contains", "containing", "contained", "_with"}
_BAND = {"band", "bands", "belt", "belts"}


def step(carry, prefix, upstream):
    raw_token = prefix.token_strings[-1].strip()
    token = raw_token.lower()
    same_document = (
        len(prefix.document_ids) > 1
        and prefix.document_ids[-1] == prefix.document_ids[-2]
    )
    previous = (
        prefix.token_strings[-2].strip().lower() if same_document else ""
    )
    if token in {"带", "帶"}:
        value = 7.7
    elif raw_token == ".have":
        value = 1.33
    elif token == "had":
        value = -0.11
    elif token == "with" and previous in {"come", "comes", "came"}:
        value = 0.72
    elif raw_token == "With":
        value = 0.32
    elif token == "加":
        value = 0.54
    elif token == "带来":
        value = 1.4
    elif token in _HAVE:
        value = 0.72
    elif token in _CARRY:
        value = 0.9
    elif token in _CONTAIN:
        value = 0.5
    elif token in _BAND:
        value = 1.3
    elif token.startswith("+") or token.endswith("+"):
        value = 0.58
    else:
        value = 0.005
    return None, float(value)

programs.sol:
"""Short non-Latin word beginnings, especially single Cyrillic letters.

Leading spaces and script changes distinguish beginnings from word interiors.
Russian short function words are less negative than incomplete word prefixes;
letter case and broad phonetic classes refine the single-letter response.
Arabic, Korean, katakana and accented Latin beginnings have weaker responses.
An unfinished Unicode character uses the preceding script as a language cue.
Everything else is near zero; repeated middle dots are a positive exception.
The constants are averages measured on training text, not token-ID lookups.
"""
import unicodedata
from functools import lru_cache

READS = ()
RUSSIAN_SHORT_WORDS = set(
    'бы во вы да до за же из ко ли мы на не ни но ну об он от по со то ты '
    'уж ей им их без был вам вас все где два для его ему еще или как кто '
    'мне мой над нас она они оно под при про раз сам так там тот три что '
    'это уже'.split()
)
VOWELS = set('аеиоуыэюяёіїє')
SIBILANTS = set('жзсцчшщ')
STOPS_AND_SONORANTS = set('бгдлмнпрт')
# Predictions for an unfinished character, conditioned on preceding text's script.
INCOMPLETE_BEGINNINGS = {
    'HANGUL': -1.41, 'CYRILLIC': -1.41,
    'HIRAGANA': -0.62, 'KATAKANA': -0.62,
    'ARABIC': -0.89, 'GREEK': -0.29,
}

@lru_cache(maxsize=65536)
def script(text):
    for character in text:
        if character.isalpha():
            name = unicodedata.name(character, '')
            return name.split()[0] if name else ''
    return ''


def cyrillic(text, spaced, previous_script):
    n = len(text)
    if n > 1:
        if not spaced:
            return 0.04
        if text.lower() in RUSSIAN_SHORT_WORDS:
            return -0.07
        if n >= 5:
            return 0.07
        if n == 4:
            return 0.0
        vowel_end = text[-1].lower() in VOWELS
        value = (-0.55 if vowel_end else -0.98) if n == 2 else (
            -0.02 if vowel_end else -0.25
        )
        return value * (0.55 if text[0].isupper() else 1.0)
    if not spaced:
        beginning = previous_script != 'CYRILLIC'
        if text.isupper():
            return -0.77 if beginning else -0.21
        if text == 'б':
            return -1.17
        if text in VOWELS or text in 'ьъ':
            return -0.15 if beginning else 0.02
        return -0.42 if beginning else -0.12
    if text.isupper():
        return -2.38 if text in 'АБЛ' else -0.94
    if text == 'а':
        return -4.09
    if text == 'в':
        return -0.10
    if text == 'к':
        return -1.55
    if text in STOPS_AND_SONORANTS:
        return -3.16
    if text in SIBILANTS:
        return -0.99
    if text in 'фх':
        return -2.04
    return -0.83


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, '', '')
    _, language, previous_script = carry
    token = prefix.token_strings[-1]
    text = token.strip()
    spaced = token.startswith(' ')
    current_script = script(text)
    n = len(text)
    value = 0.0
    if current_script == 'CYRILLIC':
        value = cyrillic(text, spaced, previous_script)
    elif current_script == 'ARABIC':
        if spaced and n == 1:
            value = -0.16 if text == 'و' else -1.06
        elif spaced and (text == 'ال' or n == 3 and text.startswith('ال')):
            value = -1.08
        else:
            value = -0.03 if spaced else 0.006
    elif current_script == 'KATAKANA':
        if n == 1:
            value = -1.2 if spaced else (
                -0.07 if previous_script == 'KATAKANA' else -0.55
            )
        else:
            value = -0.03
    elif current_script == 'HIRAGANA':
        value = 0.04
    elif current_script == 'HANGUL':
        value = -0.48 if spaced and n == 1 else 0.05
    elif current_script == 'THAI':
        value = -0.19 if n == 1 else 0.016
    elif '�' in text:
        if spaced:
            value = INCOMPLETE_BEGINNINGS.get(language, -0.18)
        else:
            value = -0.016
    elif current_script == 'LATIN' and spaced and n == 1 and ord(text) > 127:
        value = -0.14 if text in 'àé' else (
            -1.05 if text in 'áđ' else -0.27
        )
    elif text in ('،', '؟'):
        value = -0.28
    elif n >= 2 and set(text) == {'·'}:
        value = 0.75
    carry = (document, current_script or language, script(token[-1:]))
    return carry, float(value)

