programs.sol:
"""Approximate a token-final z detector from decoded spelling.

Short fragments ending in z are strongest; leading whitespace and length
weaken them.  Capitalization and the preceding letter adjust the response.
For a one-letter z, attachment to a previous letter (especially t) matters.
Several related z/ts letters also respond, as does the tool-call opener.
Only the previous character is remembered, resetting between documents.
"""
READS = ()

# Adjustments by the character immediately before a token-final Latin z.
PRECEDING_LETTER = {
    'e': 0.9, 'n': 0.9,
    'i': 0.5, 'o': 0.5, 't': 0.5,
    'u': 1.8, 'a': -0.3,
    'c': -0.7, 'd': -0.7, 'ı': -0.8,
}
# Single letters/syllables representing z or related sibilants.
RELATED_LETTERS = {
    'ず': 2.8, 'づ': 2.0,
    'ズ': 1.6, 'ヅ': 1.6, 'ツ': 1.1,
    'ц': 0.7, 'ζ': 0.7, 'ț': 0.7,
    'ź': 1.5, 'ž': 0.4, 'ż': 0.4,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.lstrip()
    lower = word.lower()
    n = len(word)
    spaced = len(word) != len(token)
    value = RELATED_LETTERS.get(lower, 0.0)
    if lower.endswith('z'):
        if n == 1:
            value = 1.8 if spaced else 3.1 if previous.isalpha() else 2.2
            if not spaced and previous.lower() == 't':
                value += 0.7
        elif not lower[-2].isalpha():
            value = 2.1
        else:
            value = 3.5 - 0.8 * spaced
            value += PRECEDING_LETTER.get(lower[-2], 0.0)
            if word[0].isupper() and not word.isupper():
                value += 0.8
            if lower[-2] == 'z':
                value -= 1.6 if n == 2 else 0.7
            if n >= 4:
                value -= 0.3 if n == 4 else 1.1 if n == 5 else 1.5
    elif 'z' in lower:
        value = -0.1 if lower.startswith('z') else 0.2
        value += 0.3 * word[0].isupper() + 0.5 * ('zz' in lower)
    elif lower.endswith('з'):
        value = 1.3
        if n > 1:
            if lower[-2] in 'еиоыв':
                value += 0.9
            elif lower[-2] == 'у':
                value += 1.7
            value -= 0.3 * (max(0, n - 2) + spaced)
    elif word.endswith('ز'):
        value = 1.9 if n == 1 else 3.4 if word[-2] == 'و' else 2.5
    elif word == '<tool_call>':
        value = 0.92
    return (doc, token[-1:]), float(max(-0.2, value))

