programs.sol:
"""A detector of scholarly/document apparatus rather than ordinary prose.
It predicts negative pulses for citations, reference markup, TeX environments,
footnotes, authorship/review statements and supplements. A small, document-local
text tail disambiguates split markers such as 'et al' and '{ref-type'.
Unrecognized text is assigned zero; this omits the component's weak background
and positive responses. The pulse sizes are rounded estimates from training.
"""
import re

READS = ()
ARTICLE_LABELS = set('''reference references introduction abstract appendix
review reviewed editor funding disclosure competing conflicting consent
anonymous availability bibliography author doi'''.split())
WRITERS = {'authors', 'manuscript', 'reviewer', 'reviewers', 'referee'}
ENVIRONMENTS = {'aligned', 'array', 'table', 'figure', 'proof', 'matrix'}


def response(s, tail):
    word = s.strip()
    w, b = word.lower(), tail.lower().rstrip()
    # Bibliographic and Markdown reference syntax.
    if w == '-type':
        return -4.6 if b.endswith('{ref') else -0.45
    if w == 'al':
        return -1.0 if re.search(r'\bet$', b) else (
            -1.4 if b.endswith('supplement') else 0.0)
    if '[@' in w and len(w) <= 4:
        return -1.4
    if w == '@':
        return -2.8 if b.endswith('([') else -0.16
    if s == '#' and (b.endswith('](') or (tail.endswith('{')
            and not re.search(r'\n\s*\{$', tail))):
        return -2.2
    if w == 'ref':
        return -0.6 if b.endswith(('{', '\\', '\\eq', 'ref-type="')) else -0.12
    if w == '="' and b.endswith(('ref-type', 'data-label')):
        return -0.85
    if w == '"}' and 'ref-type=' in b[-50:]:
        return -0.45
    if w == '{}':
        return -1.5 if b.endswith(']') else -0.4
    if w in ('fig', 'figure', 'table') and b.endswith('ref-type="'):
        return -1.5 if w == 'table' else -0.4
    # TeX structures and footnotes.
    if re.search(r'\\(?:begin|end)\{$', b):
        return -1.1 if w in ENVIRONMENTS else (-0.35 if w == 'equ' else 0.0)
    if w == 'ation' and b.endswith('{equ'):
        return -0.3
    if w.startswith('}') and b.endswith('\\end{aligned'):
        return -0.85
    if w in ('cite', 'citep', 'label') and b.endswith('\\'):
        return -0.5
    if w in ('note', 'notes') and b.endswith('foot'):
        return -2.1
    # Conventional back-matter phrases and deeply nested section headings.
    if w == '######':
        return -1.1
    if s.isspace() and tail.endswith('######'):
        return -2.1
    if w == 'file' and b.endswith('additional'):
        return -3.2
    if w in ('material', 'information', '-material') and b.endswith('supplementary'):
        return -2.8
    if w in ('interest', 'interests') and re.search(r'conflicts? of$', b):
        return -2.4
    if w in ('declare', 'declares') and b.endswith('authors'):
        return -4.0
    if w == 'consent' and b.endswith(('written', 'informed')):
        return -1.25
    if w == 'author' and b.endswith('corresponding'):
        return -1.8
    if w == 'review' and b.endswith(('peer', 'systematic')):
        return -1.15
    if re.search(r'\backnowled\w*$', (tail + s).lower()):
        return -0.45 if w in ('acknowledge', 'acknowledged', 'acknowledges') else -1.6
    if w == 'supplementary' or w in ('plement', 'plementary') and b.endswith('sup'):
        return -1.3
    if w == '稿' and b.endswith('审'):  # Chinese "review manuscript"
        return -1.1
    # Contact placeholders and documentation metadata.
    if w == '@example':
        return -1.2
    if w in ('.org', '.com') and b.endswith('@example'):
        return -1.5 if w == '.org' else -0.8
    if w == '.lastname':
        return -0.55
    if w == '.md':
        return -0.55 if b.endswith('readme') else -0.15
    if w in WRITERS:
        return -1.2 if word == w else -0.6
    if w in ARTICLE_LABELS:
        return -0.4
    if word in ('Fig', 'Figure', 'Table'):
        return -0.25
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    return (doc, (tail + s)[-96:]), float(response(s, tail))

programs.haiku:
"""Citation and reference markup detector (negative side).

layers.0.mlp.down_proj:5745 goes negative on the tokens of citation, cross-reference,
footnote and supplement markup, and of manuscript back matter (author declarations, peer
review, acknowledgements). It is near zero on ordinary prose and code. Strongest
responses, as per-token averages over real text:
  - the "-type" of an attribute like {ref-type="fig"}                  (about -4.6)
  - the "#" that opens a link target after "(" or "](", as in [Fig 1](#f1)   (about -2.1)
  - the "[@" of a pandoc citation key, as in \\[@CR16]                  (about -1.9)
  - "Material" / "file" after "Supplementary" / "Additional"            (about -2.5)
  - "notes" in "Footnotes" and "note" after "\\foot"                    (about -2.5)
  - "{}" closing a bracketed span like [*Konus*]{}                      (about -1.5)
  - "proof", "figure", "aligned" right after "\\end{"                    (about -1.1)
  - "et al": the "al" after "et"                                       (about -1.0)
  - back-matter words: "authors", "declare", "interest", "review",
    "referee", "Affiliation"                                            (about -1.5)
  - "ref", "References", "Table", "Figure", "links" (about -0.5)
Everything else is predicted as zero.  The values are per-token averages, not a fit.
"""

READS = ()

# Words of bibliographic, supplement and back-matter prose.
BACK_MATTER_WORDS = {
    " authors", "authors", " declare", "declare", " referee", "referee", "iliation", " REVIEW",
}
# Words of reference prose (weak).
REFERENCE_WORDS = {
    "ref", "References", "Reference", " Figure", "Figure", " Table", "Table", "table",
    "figure", "Fig", " links", " author", "author", " review",
}
SUPPLEMENT_LEADS = {"Supplementary", " Supplementary", "Additional", " Additional", "Supplemental"}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    prev2 = prefix.token_strings[-3] if len(prefix) > 2 else ""
    value = 0.0
    if s.startswith("-") and prev.endswith("ref"):
        value = -4.6  # the "-type" of {ref-type="fig"}: a cross-reference link attribute
    elif s.strip() == "#" and prev.endswith(("(", "{")):
        value = -2.3  # "#" opening a link or attribute target, as in ](#fig1) or {#sec2}
    elif s.strip() == "[@" or (s.strip() == "@" and prev.endswith(("[", "("))):
        value = -2.3  # citation key marker, as in \[@CR16] or ([@smith)
    elif s.strip() in ("Material", "file") and prev.strip() in SUPPLEMENT_LEADS:
        value = -2.5  # "Supplementary Material", "Additional file"
    elif s.strip() in ("notes", "note") and prev.strip().lower() == "foot":
        value = -2.5  # Footnote
    elif s == "{}":
        value = -1.0  # [text]{} span attribute
    elif prev == "{" and prev2.endswith("end"):
        value = -1.1  # \end{proof}, \end{figure}, \end{aligned}
    elif s == " al" and prev.endswith("et"):
        value = -1.0  # "et al"
    elif s in BACK_MATTER_WORDS:
        value = -1.5
    elif s == " interest" and prev == " of":
        value = -0.6  # "conflict of interest"
    elif s in SUPPLEMENT_LEADS:
        value = -1.0
    elif s in REFERENCE_WORDS:
        value = -0.5
    return carry, float(value)

