Common section labels and citation/markup tokens get a stronger response;
a few formal-document words get a smaller one, and other text is zero.
"""

READS = ()

HEADINGS = {
    "references", "bibliography", "conclusions", "appendix", "summary",
    "tags", "figure", "table", "external", "editor",
}
MARKUP = {"@", "-type", "aligned", "doi"}
FORMAL_WORDS = {"funding", "filing", "enactment", "consent", "license"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
