programs.sol:
"""A coarse spelling/style approximation, not a vocabulary lookup.

CamelCase and dotted member names, empty collection/call delimiters and escaped
quotes make the prediction more negative. Closing braces and turn boundaries
raise it. Four-to-six-letter ASCII words get a small negative correction;
file extensions and web suffixes offset the dotted-name correction. Only the
current token is used. Individual-word and context differences are left out.
"""
import re

READS = ()
METHODS = frozenset((
    'get set add append read write find create delete remove update parse '
    'split join clear load save open close insert pop push'
).split())
FILE_EXTENSIONS = frozenset((
    'py js ts jsx tsx rs java cpp h hpp c css html json xml yaml yml md '
    'txt csv sh rb go php'
).split())
WEB_DOMAINS = frozenset('com org net edu io gov'.split())
QUOTED_BRACKETS = ('("', "('", '["', "['", '")', "')", '"]', "']")


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    t = s.strip()
    word = t.isascii() and t.isalpha()
    has_alnum = any(c.isalnum() for c in t)
    camel = len(re.findall('[a-z][A-Z]', t)) if t.isascii() else 0
    member = t.startswith('.') and t[1:].isascii() and t[1:].isalpha()
    value = -0.00619
    if word and 4 <= len(t) <= 6:
        value -= 0.00540
    if camel:
        value -= 0.05406 + 0.02059 * min(camel - 1, 2)
    if member:
        value -= 0.03566
        if t[1:] in FILE_EXTENSIONS:
            value += 0.03991
        if t[1:] in WEB_DOMAINS:
            value += 0.03831
    method_context = member or (word and not s[0].isspace())
    if method_context and t.lstrip('.').lower() in METHODS:
        value -= 0.03026
    if not has_alnum:
        if '[]' in t:
            value -= 0.06822
        if any(q in t for q in QUOTED_BRACKETS):
            value -= 0.02214
    if t == '()' and '\n' not in s:
        value -= 0.02485
    if '\\"' in t:
        value -= 0.04092
    if t.startswith('}'):
        value += 0.00980
    if t in ('.', ',', ';', ':', '?', '!', '。', '，'):
        value += 0.00491
    if not t:
        value += 0.00240
    markers = ('<tool_call>', '</tool_call>', '<think>', '</think>')
    if t.startswith('<|') or t in markers:
        value += 0.01204
    if t in ('<|im_end|>', '</think>'):
        value += 0.02537
    if t == '<|endoftext|>':
        value -= 0.02165
    return None, float(value)

"""A spelling-first approximation of the 'com' feature.

Bare com fragments fire strongly, especially in Java declarations. Domain
endings .com have their own strength. Whole words sharing the syllable are
weaker; common/commonplace, compound, and several other word families are
nearly inactive. Cyrillic kom and Japanese/Thai phonetic equivalents are
included, with small came/corn/www exceptions. A 150-character buffer
amplifies Java declaration contexts and weakens bare com near Romance
accents or after acordo. It resets at document boundaries.
"""

READS = ()

# These longer word families respond little despite sharing the spelling.
WEAK_FAMILIES = (
    'common', 'communit', 'compoun', 'compact', 'commit', 'compil',
    'complic', 'compens', 'computational', 'committee',
)
ROMANCE_ACCENTS = 'ãõçáéíóúàèìòù'


def word_strength(word):
    if word.endswith('com'):
        if word.startswith(('accom', 'telecom', 'sitcom', 'locom')):
            return 0.8
        if word.startswith(('decom', 'recom')):
            return 2.3
        return 3.9
    if word in ('comm', 'comb'):
        return 2.6
    if word in ('comp', 'compr', 'compl'):
        return 1.5
    if word.startswith(WEAK_FAMILIES):
        return 0.25
    if word in ('come', 'comes', 'coming'):
        return 2.15
    if word.startswith(('comput', 'commerc', 'compos', 'comed', 'comic')):
        return 1.75
    if word.startswith(('compar', 'complex')):
        return 0.6
    if word.startswith('com'):
        return 1.0
    return 0.2 if 'com' in word else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    spelling = token.strip().strip('._-(/')
    word = spelling.lower()
    value = word_strength(word)
    if word == 'com':
        if token.strip() == '.com':
            value = 3.7 if 'https://' in recent else 4.6
        elif token.strip().startswith('_'):
            value = 6.0
        elif spelling != 'com':
            value = 6.4
        elif token.startswith(' '):
            accented = any(c in ROMANCE_ACCENTS for c in recent)
            value = 5.2 if accented else 6.8
            previous = (recent.rstrip().split() or [''])[-1]
            if previous in ('import', 'package'):
                value = 11.2
            elif previous in ('public', 'private', 'protected', 'static'):
                value = 9.0
            elif previous == 'acordo':
                value = 1.6
        else:
            value = 7.2
    elif word == 'ком':
        if token.startswith(' '):
            value = 4.2 if spelling == 'ком' else 2.8
        else:
            value = 1.5
    elif word.startswith(('ком', 'kom')):
        value = 2.1 if word == 'kom' else 1.3
    elif spelling in ('コン', 'コミ', 'コ', 'คอม'):
        value = 3.8 if spelling == 'คอม' else (0.5 if spelling == 'コ' else 1.2)
    elif word == 'came':
        value = 1.0
    elif word == 'corn':  # visually resembles com
        value = 1.8
    elif word == 'www':
        value = 0.3 if token.startswith(' ') else 0.85
    return (doc, (recent + token)[-150:]), float(value)

programs.haiku:
"""Layer-0 MLP unit 5749 (layers.0.mlp.down_proj) as a "com" spelling detector.

The unit reads the spelling of the current token. Its activation is high on the
letters "com" standing alone (" com", "com", ".com", "/com", " Com"), which is
how "com" appears in web domains, Java package names ("com.google...") and command
names. It is weaker on words that begin with com/comp/comm, weaker still on the
Russian/Polish "ком" or Latin "kom" spelling at the start of a token, and barely
responds to "com" in the middle of a word (become, income, recommend). Many common
com-words (common, community, compared, committee, compile) stay near zero. Every
other token gives 0.

Main rule, in order:
  1. token is "com" once punctuation and spaces are dropped: 6, or 9 if the current
     line has import/package/public/private/static (Java package names);
  2. word starts with com/comp/comm: 2 for come/coming/comb/comm/compute/composite,
     0.2 for the exceptions listed, 1 otherwise;
  3. word starts with ком or kom: 1.7;
  4. "com" inside a word: 0.4;
  5. anything else: 0.

The program keeps only the current line's text in its carry, reset at each document.
"""
import re

READS = ()

BARE = 6.0
JAVA = 9.0
EXCEPTIONS = {"common", "commonly", "community", "communities", "compared", "compare",
              "commit", "commitment", "committed", "committee", "compile", "compiler",
              "compilation", "compact", "compound", "compounds", "competent", "communicate"}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    line = carry[1] if carry is not None and carry[0] == doc else ""
    tok = prefix.token_strings[-1]
    word = re.sub(r"[^a-zа-я]", "", tok.lower())
    if word == "com":
        ctx = re.search(r"\b(import|package|public|private|static)\b", line)
        value = JAVA if ctx else BARE
    elif word.startswith(("com", "comp", "comm")):
        if word in EXCEPTIONS:
            value = 0.2
        elif word.startswith(("come", "coming", "comb", "comm", "compute", "computing", "composite")):
            value = 2.0
        else:
            value = 1.0
    elif word.startswith(("kom", "ком")):
        value = 1.7
    elif "com" in word:
        value = 0.4
    else:
        value = 0.0
    line = line[-300:] + tok
    if "\n" in tok:
        line = tok.split("\n")[-1]
    return (doc, line), float(value)

