"""A document-start pulse, weighted by common opening syntax.

Headings, articles, question words and code preambles have large pulses.
Other initial tokens have a modest pulse. Subsequent tokens are near zero.
Only the document label is remembered, so packed documents reset the pulse.
"""

import math

READS = ()
ARTICLES = {"The": 1.32, "A": 0.70, "An": 0.75}
QUESTIONS = frozenset({"Why", "Who", "Which", "When", "Where"})
CODE_PREAMBLES = frozenset({"from", "using", "namespace", "export"})
DECLARATIONS = frozenset({"def", "class", "function", "const", "var", "let"})


def pulse(token):
    if token in ARTICLES:
        return ARTICLES[token]
    if token.strip().lower() == "the":
        return 0.57
    if token and set(token) == {"#"}:
        n = len(token)
        if n <= 2:
            return 2.30
        if n == 3:
            return 1.78
        return 1.24 if n <= 6 else 0.45
    if token.startswith("#"):
        return 1.05
    if token in {"package", "import"}:
        return 1.63
    if token in CODE_PREAMBLES:
        return 0.88
    if token in DECLARATIONS or token == "<?":
        return 0.75
    if token in {"//", "/*", "/**"}:
        return 1.02
    if token == "What":
        return 1.84
    if token == "How":
        return 1.25
    if token in QUESTIONS:
        return 0.66
    if token == "Title":
        return 2.69
    if token in {"This", "In", "Welcome"}:
        return 0.90
    if token.startswith("<|"):
        return 0.245
    if token and set(token) == {" "}:
        return max(0.20, 0.67 - 0.12 * math.log2(len(token)))
    if token.strip().isdigit():
        return 0.25
    return 0.18


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry != document
    return document, float(pulse(prefix.token_strings[-1]) if first else 0.001)

