"""Layer-0 MLP neuron 5753 of down_proj, as a document-opening detector.

What it does: this component is almost silent inside a document (its activation there
is a small, token-specific wobble of about +-0.05 that no simple rule captures, so the
program predicts 0). Its large activations come at the first token of a document (the
first token after <|endoftext|>, or the first token of a row), and there they depend on
what kind of opener the token is:

  * markup, code and heading openers ('#', '##', '//', 'import', 'package', 'Title', ...)
    fire hardest, around 1.6;
  * question words and sentence openers ('What', 'How', 'The', 'This', 'In', ...) fire
    at about 1.0;
  * pronouns and person/service nouns ('He', 'They', 'Not', 'Service', ...) are about 0;
  * any other first token, including leading-space words and whitespace, is about 0.2.

Everything else, from the second token of a document onward, predicts 0.
"""

READS = ()

MARKUP_OPENERS = {"#", "##", "###", "//", "/*", "/*\n", '"""\n', "#include", "#!/", "#![", "#ifndef",
                  "#pragma", "<?", "import", "package", "using", "def", "from", "export", "Title"}
SENTENCE_OPENERS = {"What", "How", "Why", "Which", "When", "Can", "Does", "Is", "Are", "Do",
                    "The", "This", "In", "A", "An", "Welcome", "Question", "There", "We", "Use",
                    "Today", "For", "You", "I", "One", "Hmm"}
WEAK_OPENERS = {"He", "She", "They", "His", "Her", "Not", "Person", "Service", "Bo", "'s", "'re"}


def step(carry, prefix, upstream):
    docs = prefix.document_ids
    if len(docs) > 1 and docs[-1] == docs[-2]:
        return None, 0.0          # not the first token of its document
    s = prefix.token_strings[-1]
    if s in MARKUP_OPENERS:
        return None, 1.6
    if s in SENTENCE_OPENERS:
        return None, 1.0
    if s in WEAK_OPENERS:
        return None, 0.0
    return None, 0.2

