"""Recognize lexical names for periods and other spans.

'Period' is the strongest cue, including that token at the beginning of a
longer word. Its spelling and capitalization change the strength. Intervals,
ranges, windows, eras and a few translations give smaller negative responses.
Preceding 'time' or length modifiers weaken 'period'; 'period of' responds on
'of'. No interpretation of
whether a period means time, punctuation, or an identifier is attempted.
"""
READS = ()


def span_value(token):
    word = token.strip().lstrip('_.-(')
    lower = word.lower()
    if lower in {'period', 'periods'}:
        value = -5.8 if word[:1].isupper() else -5.05
        if lower.endswith('s'):
            value += 0.4
        if token.startswith('_'):
            value += 1.0 if lower.endswith('s') else 0.6
        elif token == word and not word[:1].isupper():
            value += 0.4
        return value
    if lower == 'periodic':
        return -1.85
    if lower == 'periodically':
        return -1.4
    # Russian and Romance spellings of 'period', including token fragments.
    if lower in {'период', 'período'}:
        return -3.5
    if lower in {'periodo', 'période', 'пери'}:
        return -2.7
    # Distinctive final fragments of 'period', also found in iodine/diode.
    if lower in {'iod', 'iode'}:
        if word.isupper():
            return -4.8
        return -2.1 if token == word else -1.5
    if lower in {'peri', 'péri', 'perí'}:
        return -0.7
    if lower in {'interval', 'intervals', 'timespan'}:
        return -1.0 if lower.endswith('s') else -1.2
    if lower in {'range', 'ranges'}:
        if lower.endswith('s'):
            return -0.5
        if token.startswith('_') or token == 'Range':
            return -0.85
        return -0.65 if token.startswith(' ') else -0.5
    if lower == 'era':
        return -0.8 if token.startswith(' ') else 0.0
    if lower == 'timeframe':
        return -0.75
    if lower == 'timeout':
        return -0.35 if token.startswith(' ') else -0.7
    if lower == 'window':
        return -0.6 if token.startswith(' ') else -0.4
    if lower in {'region', 'regions', 'phase', 'phases', 'radius'}:
        return -0.4
    if lower in {'during', 'amid'}:
        return -1.1 if lower == 'amid' else -0.15
    if lower in {'duration', 'durations'}:
        return -0.35
    # Chinese/Japanese: during a period, era/cycle, term/deadline, stage.
    if word == '期间':
        return -3.0
    if word == '期間':
        return -2.4
    if word in {'时期', '周期', '週期'}:
        return -2.0
    if word in {'期', '時期', '期限', '本期', '期内'}:
        return -1.2
    if word in {'同期', '时限', '年代', '阶段', '隔'}:
        return -0.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = span_value(token)
    if token.startswith(' ') and word in {'period', 'periods'}:
        if previous == 'time':
            value += 0.8
        elif previous in {'short', 'brief', 'long', 'longer'}:
            value += 0.45
        elif previous in {'extended', 'prolonged'}:
            value += 1.0
    if previous in {'period', 'periods'}:
        if word == 'of':
            value = -1.35 if previous == 'period' else -1.05
        elif word == 'ic':
            value = -1.15
