programs.haiku:
"""Layer-0 MLP output component 5756: a "time period" detector.

The component writes a strongly negative value into the residual stream on the
word "period" (and "periods", "Period", "_period"). The same idea in other
languages ("период", "période", "periodo") and Chinese 期 (时期, 期间, 期限)
gets a somewhat weaker negative value. "interval" gets a moderate one, and words
for ranges, regions, windows, phases and durations get weak ones. "periodic" is
only mildly negative. Every other token gets 0.

The rule reads only the current token's text, so it is a per-token lookup.
"""

READS = ()

ENGLISH_PERIOD = -5.0     # "period", "periods", "Period"
FOREIGN_PERIOD = -3.0     # "период", "période", "periodo", "пери"
CHINESE_QI = -1.0         # 期 in 时期 / 期间 / 期限 (also 期货, weakly)
INTERVAL = -1.2           # "interval", "intervals"
RANGE = -0.7              # "range", "ranges"
WEAK = -0.4               # region, window, phase, duration, era, timeframe, decade
PERIODIC = -1.7           # "periodic", "periodically"

RANGE_WORDS = {"range", "ranges", "_range", "-range"}
WEAK_WORDS = {"region", "regions", "window", "phase", "duration", "era", "timeframe", "decade"}


def activation(token):
    """The component's activation for one token, from its text."""
    word = token.lower().strip()
    if "periodic" in word:
        return PERIODIC
    if "period" in word:
        return ENGLISH_PERIOD
    if any(stem in word for stem in ("период", "пери", "période", "periodo")):
        return FOREIGN_PERIOD
    if "期" in token:
        return CHINESE_QI
    if "interval" in word:
        return INTERVAL
    if word in RANGE_WORDS:
        return RANGE
    if word in WEAK_WORDS:
        return WEAK
    return 0.0


def step(carry, prefix, upstream):
    # Each position is judged on its own token; the carry is not needed.
    return None, activation(prefix.token_strings[-1])

