"""Mark words that name a span, period, or phase of time."""

READS = ()

# The standalone English word "period" is a particularly strong cue.
STRONG_PERIODS = {"period", "periods"}
SPAN_WORDS = {"range", "ranges", "phase", "phases", "era", "region"}
ASIAN_SPANS = {"期", "时期", "同期", "隔", "간", "时限", "年代", "기간"}
OTHER_SPANS = {"период", "przed", "peri", "timeout"}


def step(carry, prefix, upstream):
    """Predict a negative pulse on period/span vocabulary, otherwise zero."""
    token = prefix.token_strings[-1].strip()
    word = token.casefold()

    if word in STRONG_PERIODS:
        value = -5.2
    elif word in {"interval", "intervals"}:
        value = -1.3
    elif word == "период":
        value = -2.9
    elif word == "时期":
        value = -2.3
    elif word in {"duration", "during"}:
        value = -0.4 if word == "duration" else -0.16
    elif word in SPAN_WORDS:
        value = -0.7
    elif token in ASIAN_SPANS or word in OTHER_SPANS:
        value = -0.9
    else:
        value = 0.0

    # Nearby connective words carry a smaller negative pulse too.
    doc = prefix.document_ids[-1]
    previous_doc, previous_word = carry if carry is not None else (None, "")
    if word == "of" and previous_doc == doc:
        if previous_word in STRONG_PERIODS:
            value = -1.4
        elif previous_word in {"range", "ranges"}:
            value = -0.18

    return (doc, word), value

programs.sol:
"""Short vowel+h syllables: strongest on ah/oh/eh, weaker on isolated h.

Length, capitalization and whether h is medial adjust the response. The
preceding character accounts for h split across a token boundary. Small
secondary responses cover interjections and h letters in several scripts.
Unrecognized spellings receive zero; this deliberately omits token-specific
quirks unrelated to these classes.
"""
import re
import unicodedata

READS = ()
VOWEL_H = dict(a=5.1, e=4.4, i=2.9, o=5.6, u=3.85)
ONSET_VOWEL_H = dict(a=4.9, e=3.3, i=1.8, o=4.3, u=3.0)
# Thai, Devanagari, Urdu, Hebrew, Latin-with-dot and Arabic h-like letters.
H_LETTERS = {'ห': 2.1, 'ฮ': 1.6, 'ह': 3.1, 'ہ': 2.4,
             'ה': 1.6, 'ḥ': 2.0, 'ح': 0.6}


def base_letter(ch):
    return unicodedata.normalize('NFD', ch.lower())[:1]


def response(token, previous):
    word = token.strip()
    low = word.lower()
    space = bool(token) and token[0].isspace()
    if not word:
        return 0.0
    if low in {'wait', 'yes', 'wow', 'hmm', 'hm', 'hey'}:
        return 0.6
    if low == 'yeah':
        return 3.6
    if word in {'啊', '哦', '哈', '呵', '哼', '嗨'}:
        return 1.55 if word in {'啊', '哦'} else 0.8
    if word in H_LETTERS:
        return 1.0 if word == 'ह' and space else H_LETTERS[word]
    if word.endswith('ه') and len(word) <= 3:
        return 1.8 if word == 'اه' else 0.9
    if low.endswith('х') and len(word) <= 2:
        return 0.65 if len(word) == 1 else 0.8
    if word in {'.h', '.H'}:
        return 1.7 if word == '.h' else 0.9

    pair = re.search('[aeiouäöü]h', low)
    if pair:
        h = pair.end() - 1
        v = base_letter(low[h - 1])
        before = sum(c.isalpha() for c in word[:h])
        after = sum(c.isalpha() for c in word[h + 1:])
        if after == 0:
            value = VOWEL_H[v] if before == 1 else ONSET_VOWEL_H[v]
            if before >= 3:
                value = 2.8 if before == 3 and v == 'a' else 1.0
        else:
            value = 0.4
            if before == 1:
                if v == 'a':
                    value = 2.3 if after <= 2 else 1.0
                elif v == 'o':
                    value = 1.7 if after == 1 else 0.6
            if low.startswith(('beh', 'coh', 'muh')):
                value = 0.9
        if low[h - 1] in 'äöü':
            value = 2.8 if before == 1 and not after else 0.5
        if word == 'Oh':
            value = 6.8 if space else 6.2
        if word in {'OH', 'AH', 'EH'}:
            value = {'OH': 4.7, 'AH': 3.5, 'EH': 2.9}[word]
        return value

    if low == 'h':
        if space:
            return 0.6 if word.isupper() else 0.33
        value = 0.65 if word.isupper() else 0.5
        return value + (1.5 if previous and base_letter(previous) in 'aeiou'
                        else 0.5 if previous.isalpha() else 0.0)
    if low.startswith('h') and not space and previous:
        if base_letter(previous) in 'aeiou':
            return 0.65 ** (len(word) - 1)
    if len(word) <= 3 and low.endswith('h'):
        if word[-1] == 'H' and not word[:-1].isupper():
            return 0.75
        if low.endswith(('ch', 'th', 'ph', 'sh')):
            return 0.0
        return 0.4 if not word[0].isalpha() else 0.75
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, token[-1:]), float(response(token, previous))

