"""Guess the activation from a token's spelling.

The largest cues are a vowel immediately followed by h (as in ah/eh/oh),
which often marks an interjection or a similar syllable. A standalone H and
short conversational reactions get a smaller guess; other tokens get zero.
"""

import re

READS = ()

_VOWEL_H = re.compile(r"[aeiouyäöü]h", re.IGNORECASE)
_EXCLAMATIONS = {"ah", "eh", "oh"}
_REACTIONS = {"hmm", "hm", "yes", "wait", "oops"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()

    if word in _EXCLAMATIONS:
        return None, 4.8
    if _VOWEL_H.search(token):
        return None, 1.4
    if word == "h":
        return None, 0.65
    if word in _REACTIONS:
        return None, 0.65
    return None, 0.0

