"""A context-sensitive response to written layout separators.

The largest negative predictions are for ampersands in LaTeX alignments,
matrices and tables. Row breaks, curly argument boundaries and table pipes
also have negative responses. Ordinary words are predicted as zero.
A 600-character suffix, a LaTeX-environment flag and document position supply
context; all reset at document boundaries. Small lexical variations are omitted.
"""
import re

READS = ()
LATEX = re.compile(
    r"\\(?:begin|end|[dt]?frac|math\w*|left|right|sqrt|sum|prod|int|lim|"
    r"[clv]?dots|ddots|cdot|times|q?quad|alpha|beta|gamma|delta|epsilon|"
    r"theta|lambda|mu|nu|xi|pi|rho|sigma|tau|phi|chi|psi|omega|vec|hat|bar|"
    r"overline|underline|text\w*|mbox|phantom|rule|nonumber|label|tag|"
    r"sin|cos|tan|log|exp|ar|xymatrix|pmatrix|hline|midrule|footnotesize)\b",
    re.IGNORECASE,
)
ENVIRONMENT = re.compile(
    r"\\(begin|end)\s*\{(?:\w*matrix|array|align\w*|cases|split|"
    r"eqnarray|gather\w*|tabular)\*?\}"
)


def response(s, before, position, environment):
    core = s.strip()
    if not any(c in s for c in "&|│{}~\\") and core != "quad":
        return 0.0
    recent = before[-200:]
    math = environment or bool(LATEX.search(before))
    row_break = "\\\\" in recent

    if "&" in s:
        if "&#" in s:
            return 0.0 if s.startswith(" ") else 0.22
        if re.search(r"&(?:amp|lt|gt|quot|apos|nbsp)\b", s):
            return -0.1
        if ">&" in s:
            return -0.33
        if "(&" in s:
            return 0.12
        if math:
            if "=" in s:
                return -3.35 if "&=" in s else -4.1
            if "&&" in s:
                return -4.6
            return -6.3 if environment or row_break else -4.5
        if "&&" in s:
            return -0.1 if before[-1:].isalpha() else -0.35
        if row_break:
            return -5.9 if recent.count("&") >= 5 else -3.4
        if any(c.isalpha() for c in s) or "}" in s:
            return -1.0
        return -0.05 - 3.6 / (1.0 + position)

    if "│" in s:
        return -0.54
    if core in ("|", "||"):
        if "\n" in s:
            return 0.08 if s.startswith(" ") else 0.16
        if core == "||":
            return -0.02
        line = re.split(r"\n|\\n", before)[-1]
        pipes = recent.count("|")
        if position == 0:
            return -0.75
        if pipes >= 7:
            if line.startswith("|") and before[-1:].isspace():
                return -1.15
            return -0.5 if s.startswith(" ") else -0.25
        if "|" in line:
            return -0.3 if s.startswith(" ") else -0.1
        return -0.35 if position < 6 else (-0.12 if pipes else 0.05)

    if "\\\\" in s and not any(c.isalpha() for c in s):
        value = -1.6 if math else -0.42 - 1.6 / (1.0 + position / 3.0)
        return value - 0.35 * s.startswith(" ")
    if "}{" in s:
        environment_argument = re.search(r"\\(?:begin|end)\{[\w*]+$", before)
        return -2.0 if environment_argument else -0.85
    if core == "quad" and re.search(r"\\q?$", before):
        return -1.8 if before.endswith("q") else -1.1
    if core in ("~", "~~"):
        return -1.0 if math else -0.08
    if any(c.isalpha() for c in s):
        return 0.0
    if "{}" in s:
        return -0.95 if math else -0.3
    if "){" in s:
        return -0.9 if math else -0.27
    if math and "}" in s:
        return -0.6 if s.startswith(" ") else (-0.4 if "\n" in s else -0.15)
    if math and s.startswith(" ") and "{" in s:
        return -0.35
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, "", False)
    _, position, before, environment = carry
    s = prefix.token_strings[-1]
    value = response(s, before, position, environment)
    joined = before + s
    if "}" in s:
        for match in ENVIRONMENT.finditer(joined[-150:]):
            if match.end() + max(0, len(joined) - 150) > len(before):
                environment = match.group(1) == "begin"
    return (doc, position + 1, joined[-600:], environment), float(value)

